files.popup.css:
@property --spin {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

:root {
  color-scheme: dark;
  --bg: #050a18;
  --bg-2: #0a1428;
  --surface: rgba(148, 180, 255, .045);
  --surface-2: rgba(148, 180, 255, .075);
  --surface-3: rgba(148, 180, 255, .11);
  --line: rgba(148, 180, 255, .1);
  --line-2: rgba(148, 180, 255, .18);
  --text: #eef3ff;
  --muted: #9eacc9;
  --faint: #64739a;
  --sky: #38bdf8;
  --blue: #3b82f6;
  --indigo: #6366f1;
  --ice: #bae6fd;
  --ink: #04102a;
  --ok: #34d399;
  --warn: #fbbf24;
  --bad: #f87171;
  --grad: linear-gradient(120deg, #38bdf8 0%, #3b82f6 50%, #6366f1 100%);
  --radius: 16px;
  --ease: cubic-bezier(.2, .8, .2, 1);
  --font: "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", sans-serif;
  --font-display: "Segoe UI Variable Display", "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: "Cascadia Mono", "SF Mono", ui-monospace, Consolas, monospace;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

html, body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 13px/1.45 var(--font);
  -webkit-font-smoothing: antialiased;
}
/* La larghezza la decide il guscio (popup.html): così la barra di scorrimento non taglia il contenuto. */
body { position: relative; width: auto; overflow-x: hidden; min-height: 540px; }

/* Barra di scorrimento sottile e discreta, si accende solo al passaggio del mouse. */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track, ::-webkit-scrollbar-corner { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(148, 180, 255, .16);
  border: 2px solid transparent;
  border-radius: 8px;
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:hover { background-color: rgba(148, 180, 255, .34); }
::-webkit-scrollbar-thumb:active { background-color: rgba(56, 189, 248, .55); }
::-webkit-scrollbar-button { display: none; height: 0; }
body.tab { width: auto; min-height: 100vh; }
body.tab main { max-width: 480px; margin: 28px auto 40px; }
body.tab .top { border-radius: 20px; }

button, input { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: default; }
svg { flex: none; }
:focus-visible { outline: 2px solid var(--sky); outline-offset: 2px; }

/* ---------- Sfondo ---------- */

.aurora { position: fixed; inset: 0; z-index: 0; pointer-events: none; overflow: hidden; }
.aurora i { position: absolute; width: 360px; height: 360px; border-radius: 50%; filter: blur(72px); opacity: .34; }
.aurora i:nth-child(1) { left: -160px; top: -170px; background: #1d4ed8; animation: drift 18s ease-in-out infinite alternate; }
.aurora i:nth-child(2) { right: -170px; top: -110px; background: #0ea5e9; opacity: .24; animation: drift 22s ease-in-out infinite alternate-reverse; }
.aurora i:nth-child(3) { left: 25%; top: 440px; background: #4f46e5; opacity: .18; animation: drift 26s ease-in-out infinite alternate; }
@keyframes drift { to { transform: translate(40px, 30px) scale(1.15); } }

main { position: relative; z-index: 1; padding: 0 14px 12px; }

/* ---------- Intestazione ---------- */

.top {
  position: sticky; top: 0; z-index: 5;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  margin: 0 -14px; padding: 14px 14px 12px;
  background: linear-gradient(180deg, rgba(5, 10, 24, .94) 60%, rgba(5, 10, 24, 0));
  backdrop-filter: blur(10px);
}
.brand { display: flex; align-items: center; gap: 11px; min-width: 0; }
.logo { width: 36px; height: 36px; filter: drop-shadow(0 6px 16px rgba(59, 130, 246, .45)); }
h1 { margin: 0; font: 700 16px/1.15 var(--font-display); letter-spacing: -.2px; display: flex; align-items: center; gap: 7px; }
.version {
  padding: 1px 6px; border-radius: 6px; font-size: 10px; font-weight: 700; letter-spacing: .3px;
  color: var(--ink); background: var(--grad);
}
.brand p { margin: 2px 0 0; color: var(--muted); font-size: 11.5px; }
.top-actions { display: flex; align-items: center; gap: 6px; }

.icon-btn {
  display: grid; place-items: center; width: 32px; height: 32px; padding: 0;
  border: 1px solid var(--line); border-radius: 10px; background: var(--surface);
  color: var(--muted); transition: background .2s, color .2s, border-color .2s, transform .2s var(--ease);
}
.icon-btn:hover { background: var(--surface-3); color: var(--text); border-color: var(--line-2); }
.icon-btn:active { transform: scale(.94); }
.icon-btn svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn.small { width: 28px; height: 28px; border-radius: 9px; }
.icon-btn.small svg { width: 15px; height: 15px; }
.chip-warn {
  height: 26px; padding: 0 9px; border: 1px solid rgba(251, 191, 36, .35); border-radius: 999px;
  background: rgba(251, 191, 36, .12); color: var(--warn); font-size: 11px; font-weight: 700;
}

/* ---------- Schede ---------- */

.seg {
  position: relative; display: grid; grid-template-columns: 1fr 1fr; padding: 4px; margin: 2px 0 12px;
  border: 1px solid var(--line); border-radius: 14px; background: rgba(148, 180, 255, .03);
}
.seg-thumb {
  position: absolute; top: 4px; bottom: 4px; left: 4px; width: calc(50% - 4px); border-radius: 10px;
  background: linear-gradient(180deg, rgba(96, 165, 250, .22), rgba(59, 130, 246, .1));
  box-shadow: 0 1px 0 rgba(186, 230, 253, .14) inset, 0 6px 18px rgba(0, 0, 0, .35);
  transition: transform .35s var(--ease);
}
.seg[data-tab="verify"] .seg-thumb { transform: translateX(100%); }
.seg button {
  position: relative; z-index: 1; display: flex; align-items: center; justify-content: center; gap: 7px;
  height: 34px; border: 0; border-radius: 10px; background: none; color: var(--muted);
  font-weight: 650; transition: color .25s;
}
.seg button[aria-selected="true"] { color: var(--text); }
.seg button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.seg button[aria-selected="true"] svg { stroke: var(--sky); }
.count {
  min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; display: inline-grid; place-items: center;
  background: var(--warn); color: var(--ink); font-size: 10.5px; font-weight: 800;
}

.panel { animation: rise .35s var(--ease); }
@keyframes rise { from { opacity: 0; transform: translateY(6px); } }

/* ---------- Guida: avanzamento ---------- */

.stepper {
  --done: 0;
  position: relative; list-style: none; display: grid; grid-template-columns: repeat(4, 1fr); margin: 0 0 10px; padding: 0;
}
.stepper::before, .stepper::after {
  content: ""; position: absolute; left: 12.5%; right: 12.5%; top: 11px; height: 2px; border-radius: 2px;
}
.stepper::before { background: var(--line-2); }
.stepper::after {
  right: auto; width: calc(75% * var(--done) / 3); background: var(--grad);
  box-shadow: 0 0 12px rgba(56, 189, 248, .55); transition: width .6s var(--ease);
}
.stepper li { position: relative; z-index: 1; display: flex; justify-content: center; }
.stepper button {
  display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 0 4px 2px; border: 0; border-radius: 10px;
  background: none; color: inherit; cursor: default;
}
.stepper li.past button:not(:disabled) { cursor: pointer; }
.stepper li.past button:not(:disabled):hover i { transform: scale(1.1); box-shadow: 0 0 0 4px rgba(59, 130, 246, .2); }
.stepper li.past button:not(:disabled):hover span { color: var(--sky); }
.stepper i {
  display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; font: 800 11px/1 var(--font); font-style: normal;
  background: var(--bg-2); border: 1.5px solid var(--line-2); color: var(--faint);
  transition: background .35s, border-color .35s, color .35s, box-shadow .35s, transform .35s var(--ease);
}
.stepper span { color: var(--faint); font-size: 10.5px; font-weight: 700; letter-spacing: .2px; transition: color .35s; }
.stepper li.past i { background: var(--blue); border-color: var(--blue); color: #fff; }
.stepper li.past span { color: var(--muted); }
.stepper li.now i {
  background: var(--grad); border-color: transparent; color: #fff; transform: scale(1.12);
  box-shadow: 0 0 0 4px rgba(56, 189, 248, .16), 0 6px 18px rgba(59, 130, 246, .5);
}
.stepper li.now span { color: var(--text); }

/* ---------- Guida: coach ---------- */

/* Titolo della schermata: una sola frase che dice cosa fare adesso. */
.coach {
  --tone: var(--sky);
  display: grid; grid-template-columns: 38px 1fr; gap: 12px; align-items: start; margin: 2px 0 14px; padding: 2px 2px 0;
}
.coach.ok { --tone: var(--ok); }
.coach.warn { --tone: var(--warn); }
.coach.bad { --tone: var(--bad); }
.coach.pulse > * { animation: coach .45s var(--ease); }
@keyframes coach { from { opacity: 0; transform: translateY(5px); } }
.coach-icon {
  position: relative; display: grid; place-items: center; width: 38px; height: 38px; border-radius: 13px; color: #fff;
  background: var(--grad); box-shadow: 0 8px 20px rgba(59, 130, 246, .42);
}
.coach.ok .coach-icon, .coach.warn .coach-icon, .coach.bad .coach-icon {
  background: color-mix(in srgb, var(--tone) 18%, transparent); color: var(--tone);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--tone) 35%, transparent) inset;
}
.coach-icon svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2.3; stroke-linecap: round; stroke-linejoin: round; }
.coach-icon svg.fill { fill: currentColor; stroke: none; animation: twinkle 3s ease-in-out infinite; }
.coach-icon.spin::after {
  content: ""; position: absolute; inset: -3px; border-radius: 15px; border: 2px solid transparent;
  border-top-color: var(--sky); border-right-color: var(--sky); animation: rot 1s linear infinite;
}
@keyframes twinkle { 50% { transform: scale(.88) rotate(12deg); opacity: .85; } }
.coach > div { display: flex; flex-direction: column; min-width: 0; padding-top: 1px; }
.coach h2 { margin: 0; font: 750 17px/1.25 var(--font-display); letter-spacing: -.3px; text-wrap: balance; }
.coach p { margin: 4px 0 0; color: #c2cfea; font-size: 12.5px; line-height: 1.45; text-wrap: pretty; }
.coach p b { color: var(--text); font-weight: 700; }

.guide-step { display: flex; flex-direction: column; animation: rise .4s var(--ease); }

/* ---------- Guida: illustrazione ---------- */

.hero-art { position: relative; height: 104px; margin: -2px 0 12px; display: grid; place-items: center; }
.hero-glow { position: absolute; width: 170px; height: 110px; border-radius: 50%; background: radial-gradient(closest-side, rgba(59, 130, 246, .38), transparent); filter: blur(6px); }
.hero-film { position: relative; width: 136px; height: 104px; animation: float 5s ease-in-out infinite; }
@keyframes float { 50% { transform: translateY(-5px) rotate(-1.5deg); } }
.hero-badge {
  position: absolute; left: calc(50% + 36px); top: 56px; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  background: var(--ok); box-shadow: 0 0 0 4px var(--bg), 0 8px 20px rgba(52, 211, 153, .45); animation: badge 5s ease-in-out infinite;
}
.hero-badge svg { width: 17px; height: 17px; fill: none; stroke: var(--ink); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
@keyframes badge { 50% { transform: translateY(-5px) scale(1.06); } }
.spark { position: absolute; width: 6px; height: 6px; border-radius: 2px; background: var(--ice); transform: rotate(45deg); animation: spark 2.6s ease-in-out infinite; }
.spark.s1 { left: calc(50% - 82px); top: 24px; }
.spark.s2 { left: calc(50% + 74px); top: 16px; background: var(--sky); animation-delay: .7s; }
.spark.s3 { left: calc(50% - 64px); top: 92px; background: var(--indigo); animation-delay: 1.4s; }
@keyframes spark { 0%, 100% { opacity: .2; transform: rotate(45deg) scale(.6); } 50% { opacity: 1; transform: rotate(45deg) scale(1.15); } }

/* ---------- Guida: risposte ---------- */

.answers { display: grid; gap: 8px; }
.answer {
  position: relative; display: grid; grid-template-columns: 40px 1fr 18px; gap: 12px; align-items: center; width: 100%;
  padding: 12px 14px; text-align: left; border-radius: 17px; border: 1px solid var(--line-2); background: var(--surface);
  transition: transform .25s var(--ease), border-color .25s, background .25s, box-shadow .25s;
}
.answer:hover { transform: translateY(-1px); border-color: rgba(56, 189, 248, .45); background: var(--surface-2); box-shadow: 0 12px 28px rgba(2, 8, 30, .45); }
.answer:active { transform: scale(.985); }
.answer.primary {
  border-color: transparent; color: #fff;
  background: linear-gradient(115deg, rgba(56, 189, 248, .95), rgba(59, 130, 246, .95) 55%, rgba(99, 102, 241, .95));
  box-shadow: 0 14px 34px rgba(59, 130, 246, .38), 0 1px 0 rgba(255, 255, 255, .3) inset;
}
.answer.primary:hover { filter: brightness(1.06); box-shadow: 0 18px 40px rgba(59, 130, 246, .5), 0 1px 0 rgba(255, 255, 255, .3) inset; }
.answer-ic { display: grid; place-items: center; width: 40px; height: 40px; border-radius: 13px; background: rgba(59, 130, 246, .16); color: var(--sky); }
.answer.primary .answer-ic { background: rgba(255, 255, 255, .2); color: #fff; }
.answer-ic svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.answer-text { display: flex; flex-direction: column; min-width: 0; }
.answer-text b { font: 700 14.5px/1.25 var(--font-display); letter-spacing: -.1px; }
.answer-text small { color: var(--muted); font-size: 11.5px; margin-top: 1px; }
.answer.primary .answer-text small { color: rgba(255, 255, 255, .85); }
.answer-go { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; opacity: .7; transition: transform .25s var(--ease); }
.answer:hover .answer-go { transform: translateX(3px); opacity: 1; }

.get-preset, .more, .hb-alt { border-radius: 16px; }
.get-preset { margin-top: 12px; padding: 4px 12px; background: var(--surface); border: 1px solid var(--line); }
.get-preset summary, .more summary, .hb-alt summary {
  list-style: none; cursor: pointer; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 8px 2px; border-radius: 10px;
}
.get-preset summary::-webkit-details-marker, .more summary::-webkit-details-marker, .hb-alt summary::-webkit-details-marker { display: none; }
.get-preset summary > span:not(.sum-ic), .more summary > span:not(.sum-ic), .hb-alt summary > span { display: flex; flex-direction: column; min-width: 0; margin-right: auto; }
.get-preset summary b, .more summary b, .hb-alt summary b { font-size: 12.5px; font-weight: 700; }
.get-preset summary small, .more summary small, .hb-alt summary small { color: var(--muted); font-size: 11.5px; }
.chev {
  width: 18px; height: 18px; flex: none; fill: none; stroke: var(--muted); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;
  transition: transform .25s var(--ease);
}
details[open] > summary .chev { transform: rotate(180deg); }
.get-preset summary:hover b, .more summary:hover b, .hb-alt summary:hover b { color: var(--sky); }
.sum-ic {
  display: grid; place-items: center; flex: none; width: 30px; height: 30px; border-radius: 10px; color: var(--sky);
  background: rgba(56, 189, 248, .12); border: 1px solid rgba(56, 189, 248, .22);
}
.sum-ic svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.mini-lead { margin: 2px 2px 8px; color: var(--muted); font-size: 11.5px; }
.preset-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 4px 0 6px; }
.preset-grid button {
  display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 11px 6px 9px; border-radius: 13px;
  border: 1px solid var(--line-2); background: var(--surface-2); transition: border-color .2s, background .2s, transform .2s var(--ease);
}
.preset-grid button:hover { border-color: rgba(56, 189, 248, .5); background: rgba(56, 189, 248, .08); transform: translateY(-1px); }
.preset-grid button.saved { border-color: rgba(52, 211, 153, .5); background: rgba(52, 211, 153, .08); }
.preset-grid b { font-size: 12px; font-weight: 700; }
.preset-grid small { color: var(--muted); font-size: 10.5px; font-variant-numeric: tabular-nums; }
.shape { display: block; margin-bottom: 5px; border-radius: 4px; border: 2px solid var(--sky); background: rgba(56, 189, 248, .14); }
.shape.tall { width: 16px; height: 26px; }
.shape.square { width: 22px; height: 22px; margin-top: 2px; margin-bottom: 7px; }
.shape.wide { width: 30px; height: 17px; margin-top: 5px; margin-bottom: 9px; }

.link-btn {
  display: inline-flex; align-items: center; gap: 4px; align-self: flex-start; margin-top: 10px; padding: 4px 6px; border: 0; border-radius: 8px;
  background: none; color: var(--muted); font-size: 12px; font-weight: 650;
}
.link-btn:hover { color: var(--sky); }
.link-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.link-btn.center { align-self: center; }
.link-btn b { color: var(--text); font-weight: 700; max-width: 170px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* Nuova versione disponibile */
.update-banner {
  display: grid; grid-template-columns: 30px 1fr auto; gap: 10px; align-items: center; margin: -4px 0 12px; padding: 9px 11px;
  border-radius: 14px; border: 1px solid rgba(52, 211, 153, .3); background: rgba(52, 211, 153, .07); animation: rise .4s var(--ease);
}
.update-ic { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 10px; color: var(--ok); background: rgba(52, 211, 153, .14); }
.update-ic svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.update-text { display: flex; flex-direction: column; min-width: 0; }
.update-text b { font-size: 12.5px; }
.update-text small { color: var(--muted); font-size: 11px; }
.update-link {
  padding: 6px 10px; border-radius: 10px; font-size: 12px; font-weight: 750; text-decoration: none; white-space: nowrap;
  color: var(--ink); background: linear-gradient(90deg, var(--ok), #a7f3d0);
}

/* Primo schermo: la ricetta consigliata (master → HandBrake con il preset) prima di trascinare */
.recipe { border-color: rgba(56, 189, 248, .28); background: radial-gradient(120% 70% at 100% 0%, rgba(56, 189, 248, .1), transparent 60%), var(--surface); }
.recipe-head { display: flex; flex-direction: column; align-items: flex-start; gap: 5px; }
.recipe-head strong { font: 700 14px/1.25 var(--font-display); letter-spacing: -.1px; }
.recipe-badge {
  padding: 1px 8px; border-radius: 999px; font-size: 10px; font-weight: 800; letter-spacing: .5px; text-transform: uppercase;
  color: var(--ink); background: linear-gradient(90deg, var(--sky), var(--ice));
}
.recipe-steps { list-style: none; counter-reset: recipe; display: grid; gap: 0; margin: 12px 0 0; padding: 0; }
.recipe-steps li { counter-increment: recipe; position: relative; display: grid; grid-template-columns: 26px 1fr; column-gap: 10px; padding-bottom: 12px; }
.recipe-steps li::before {
  content: counter(recipe); grid-row: span 2; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; z-index: 1;
  background: var(--grad); color: #fff; font-size: 11px; font-weight: 800; box-shadow: 0 4px 12px rgba(59, 130, 246, .35);
}
.recipe-steps li:not(:last-child)::after { content: ""; position: absolute; left: 12px; top: 26px; bottom: 1px; width: 2px; border-radius: 2px; background: linear-gradient(rgba(59, 130, 246, .5), rgba(59, 130, 246, .08)); }
.recipe-steps li:last-child { padding-bottom: 0; }
.recipe-steps li > div:first-of-type { display: flex; flex-direction: column; padding-top: 2px; min-width: 0; }
.recipe-steps b { font-size: 12.5px; font-weight: 700; }
.recipe-steps span { color: var(--muted); font-size: 11.5px; }
.recipe-steps .preset-grid { grid-column: 2; margin: 8px 0 0; }
.or-line { display: flex; align-items: center; gap: 10px; margin: 14px 2px 12px; color: var(--muted); font-size: 11.5px; font-weight: 600; text-align: center; }
.or-line::before, .or-line::after { content: ""; flex: 1; min-width: 14px; height: 1px; background: var(--line-2); }
.drop.compact { padding: 20px 16px 16px; }
.drop.compact .drop-art { width: 60px; height: 60px; margin-bottom: 6px; }
.drop.compact .drop-art svg { width: 36px; height: 36px; }
.drop.compact .drop-orbit { border-radius: 20px; }

.origin { display: grid; gap: 8px; animation: rise .4s var(--ease); }
.origin .helper { margin-top: 2px; }
.guess {
  margin-left: 6px; padding: 1px 7px; border-radius: 999px; vertical-align: 1px; font-style: normal; font-size: 10px; font-weight: 800;
  color: var(--ink); background: linear-gradient(90deg, var(--sky), var(--ice));
}
.origin .answer.suggested { border-color: rgba(56, 189, 248, .55); background: rgba(56, 189, 248, .08); }

/* ---------- Zona di rilascio ---------- */

.assure { list-style: none; display: flex; justify-content: center; flex-wrap: wrap; gap: 6px 14px; margin: 12px 0 0; padding: 0; }
.assure li { display: flex; align-items: center; gap: 5px; color: var(--muted); font-size: 11.5px; font-weight: 600; }
.assure svg { width: 14px; height: 14px; fill: none; stroke: var(--sky); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.drop {
  position: relative; isolation: isolate; display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 34px 18px 22px; border-radius: 22px; text-align: center; cursor: pointer;
  background: radial-gradient(120% 90% at 50% 0%, rgba(56, 189, 248, .09), transparent 60%), rgba(148, 180, 255, .03);
  transition: transform .3s var(--ease), background .3s;
}
.drop::before {
  content: ""; position: absolute; inset: 0; z-index: -1; padding: 1.5px; border-radius: inherit;
  background: conic-gradient(from var(--spin), rgba(56, 189, 248, .7), rgba(59, 130, 246, .12), rgba(99, 102, 241, .65), rgba(59, 130, 246, .12), rgba(56, 189, 248, .7));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude;
  animation: spin 7s linear infinite;
}
.drop:hover { transform: translateY(-1px); background: radial-gradient(120% 90% at 50% 0%, rgba(56, 189, 248, .14), transparent 60%), rgba(148, 180, 255, .045); }
.drop.drag { transform: scale(1.015); background: radial-gradient(120% 100% at 50% 0%, rgba(56, 189, 248, .22), transparent 65%), rgba(148, 180, 255, .06); }
.drop.drag::before { animation-duration: 1.6s; }
@keyframes spin { to { --spin: 360deg; } }
.drop input { position: absolute; inset: 0; opacity: 0; cursor: pointer; }
.drop-art { position: relative; display: grid; place-items: center; width: 80px; height: 80px; margin-bottom: 10px; }
.drop-art svg { width: 46px; height: 46px; fill: none; stroke: var(--text); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; transition: transform .35s var(--ease); animation: nudge 2.4s ease-in-out infinite; }
@keyframes nudge { 50% { transform: translateY(-3px); } }
.drop-orbit {
  position: absolute; inset: 0; border-radius: 26px;
  background: linear-gradient(145deg, rgba(56, 189, 248, .2), rgba(99, 102, 241, .2));
  box-shadow: 0 0 0 1px rgba(186, 230, 253, .1) inset, 0 14px 40px rgba(59, 130, 246, .2);
}
.drop-title { font: 700 17.5px/1.2 var(--font-display); letter-spacing: -.2px; }
.drop-sub { color: var(--muted); font-size: 12px; }
.drop-sub u { text-decoration-color: rgba(56, 189, 248, .7); text-underline-offset: 3px; color: var(--text); }

/* ---------- File ---------- */

.report { display: grid; gap: 10px; animation: rise .35s var(--ease); }
.file-card {
  display: grid; grid-template-columns: 92px 1fr auto; gap: 12px; align-items: center;
  padding: 8px; border-radius: 18px; background: var(--surface); border: 1px solid var(--line);
}
.thumb {
  position: relative; width: 92px; height: 66px; border-radius: 12px; overflow: hidden;
  background: linear-gradient(135deg, #0f1c38, #081022); display: grid; place-items: center;
}
.thumb video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity .4s; }
.thumb.ready video { opacity: 1; }
.thumb-fallback { width: 26px; height: 26px; fill: none; stroke: var(--faint); stroke-width: 1.6; stroke-linejoin: round; }
.thumb.ready .thumb-fallback { display: none; }
.thumb-dur {
  position: absolute; bottom: 4px; right: 4px; padding: 1px 5px; border-radius: 5px;
  background: rgba(2, 6, 20, .65); backdrop-filter: blur(4px); font-size: 9.5px; font-weight: 700; letter-spacing: .2px;
}
.thumb-dur:empty { display: none; }
.file-info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.file-info strong { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.file-info > span { color: var(--muted); font-size: 11.5px; font-variant-numeric: tabular-nums; }
.mini-chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 3px; }
.mini-chips:empty { display: none; }
.mini-chips span { padding: 1px 6px; border-radius: 6px; background: var(--surface-2); color: var(--muted); font-size: 10px; font-weight: 650; }
.mini-chips span.hb { color: var(--ink); background: linear-gradient(90deg, var(--sky), var(--ice)); }

/* ---------- Verdetto ---------- */

.verdict {
  --accent: var(--sky);
  position: relative; padding: 14px 16px; border-radius: 20px; overflow: hidden;
  background: radial-gradient(140% 90% at 0% 0%, color-mix(in srgb, var(--accent) 15%, transparent), transparent 55%), var(--surface);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  transition: border-color .4s, background .4s;
}
.verdict-top { display: flex; align-items: center; gap: 14px; }

/* Requisiti principali: ok, oppure "verrà sistemato" con il valore di arrivo */
.key-checks { list-style: none; display: grid; gap: 2px; margin: 12px 0 0; padding: 10px 0 0; border-top: 1px solid var(--line); }
.key-checks li {
  --c: var(--ok);
  display: grid; grid-template-columns: 22px 1fr auto; gap: 10px; align-items: center; padding: 5px 2px;
  animation: rise .4s var(--ease) both;
}
.key-checks li.fix { --c: var(--sky); }
.key-checks li.warn { --c: var(--warn); }
.key-checks li.info { --c: var(--muted); }
.key-checks .kc-ic { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; color: var(--c); background: color-mix(in srgb, var(--c) 16%, transparent); }
.key-checks .kc-ic svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
.key-checks .kc-label { color: var(--muted); font-size: 12px; }
.key-checks .kc-value { display: flex; align-items: center; gap: 6px; font-weight: 700; font-size: 12.5px; font-variant-numeric: tabular-nums; }
.key-checks li.fix .kc-value s { color: var(--faint); font-weight: 600; text-decoration-color: rgba(56, 189, 248, .6); }
.key-checks .kc-to {
  padding: 1px 7px; border-radius: 999px; color: var(--ink); background: linear-gradient(90deg, var(--sky), var(--ice)); font-size: 11.5px;
}
.verdict.ready { --accent: var(--ok); }
.verdict.warn { --accent: var(--warn); }
.verdict.needs-fix { --accent: var(--blue); }
.verdict.bad { --accent: var(--bad); }
.ring { position: relative; flex: none; width: 64px; height: 64px; }
.ring svg { width: 64px; height: 64px; transform: rotate(-90deg); overflow: visible; }
.ring .track { fill: none; stroke: rgba(148, 180, 255, .1); stroke-width: 5; }
.ring .seg-arc { fill: none; stroke-width: 5; stroke-linecap: round; transition: stroke-dasharray .7s var(--ease); }
.ring .seg-arc.ok { stroke: var(--ok); }
.ring .seg-arc.warn { stroke: var(--warn); }
.ring .seg-arc.bad { stroke: var(--blue); }
.ring .seg-arc.info { stroke: #3a4a6e; }
.ring .spinner { fill: none; stroke: var(--sky); stroke-width: 5; stroke-linecap: round; transform-origin: 36px 36px; animation: rot 1s linear infinite; }
@keyframes rot { to { transform: rotate(360deg); } }
.ring-icon { position: absolute; inset: 0; display: grid; place-items: center; color: var(--accent); }
.ring-icon svg { width: 26px; height: 26px; transform: none; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; animation: pop .5s var(--ease); }
@keyframes pop { from { transform: scale(.4); opacity: 0; } }
.verdict-text { display: flex; flex-direction: column; min-width: 0; }
.kicker { color: var(--accent); font-size: 10.5px; font-weight: 800; letter-spacing: .9px; text-transform: uppercase; }
.verdict-text strong { font: 700 16.5px/1.2 var(--font-display); letter-spacing: -.2px; margin: 2px 0 3px; }
.verdict-text span:last-child { color: var(--muted); font-size: 12px; }

/* ---------- Bitrate ---------- */

.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.stat {
  --accent: var(--text);
  position: relative; display: flex; flex-direction: column; padding: 11px 12px 10px; border-radius: 16px; overflow: hidden;
  background: var(--surface); border: 1px solid var(--line);
}
.stat::after {
  content: ""; position: absolute; left: 12px; right: 12px; bottom: 0; height: 2px; border-radius: 2px;
  background: var(--accent); opacity: .7;
}
.stat.ok { --accent: var(--ok); }
.stat.warn { --accent: var(--warn); }
.stat.bad { --accent: var(--bad); }
.stat.cool { --accent: var(--sky); }
.stat-label { color: var(--muted); font-size: 10.5px; font-weight: 700; letter-spacing: .5px; text-transform: uppercase; }
.stat-value { font: 750 23px/1.1 var(--font-display); letter-spacing: -.5px; margin: 5px 0 1px; font-variant-numeric: tabular-nums; }
.stat-sub { color: var(--faint); font-size: 10.5px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.stat-sub b { color: var(--muted); font-weight: 650; }
.stats.loading .stat-value { color: transparent; border-radius: 6px; width: 70%; background: linear-gradient(90deg, var(--surface-2), var(--surface-3), var(--surface-2)); background-size: 200% 100%; animation: shimmer 1.2s linear infinite; }
@keyframes shimmer { to { background-position: -200% 0; } }
.note-line {
  margin: -2px 2px 0; padding: 8px 10px; border-radius: 12px; font-size: 11.5px; color: #fde7a8;
  background: rgba(251, 191, 36, .08); border: 1px solid rgba(251, 191, 36, .2);
}

/* ---------- Schede generiche ---------- */

.card { margin: 0; padding: 14px; border-radius: 18px; background: var(--surface); border: 1px solid var(--line); }
.card-head { display: flex; align-items: flex-start; gap: 11px; }
.card-head > div { display: flex; flex-direction: column; min-width: 0; }
.card-head strong { font-weight: 700; font-size: 13.5px; }
.card-head > div > span { color: var(--muted); font-size: 12px; margin-top: 2px; }
.card-head.slim { align-items: center; justify-content: space-between; margin-bottom: 10px; }
.card-head.slim strong { font-size: 12.5px; }
.card-icon {
  --accent: var(--sky);
  flex: none; width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; color: var(--accent);
  background: color-mix(in srgb, var(--accent) 14%, transparent); border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);
}
.card-icon.blue { --accent: var(--blue); }
.card-icon.ok { --accent: var(--ok); }
.card-icon.warn { --accent: var(--warn); }
.card-icon.bad { --accent: var(--bad); }
.card-icon.info { --accent: var(--muted); }
.card-icon svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
.pill {
  padding: 2px 8px; border-radius: 999px; font-size: 10.5px; font-weight: 750; white-space: nowrap;
  background: var(--surface-2); color: var(--muted);
}
.pill.ok { background: rgba(52, 211, 153, .13); color: var(--ok); }
.pill.warn { background: rgba(251, 191, 36, .13); color: var(--warn); }
.pill.bad { background: rgba(248, 113, 113, .14); color: var(--bad); }

/* ---------- Dettagli tecnici ---------- */

.more { padding: 2px 12px; background: var(--surface); border: 1px solid var(--line); }
.more[open] { padding-bottom: 12px; }
.more-body { display: grid; gap: 10px; margin-top: 4px; }
.more-body .card { background: rgba(148, 180, 255, .03); }

/* ---------- Grafico ---------- */

.chart { padding-bottom: 10px; }
.legend { display: flex; align-items: center; gap: 4px; color: var(--faint); font-size: 10px; font-variant-numeric: tabular-nums; }
.legend i { width: 7px; height: 7px; border-radius: 2px; margin-left: 4px; }
.lg-ok { background: linear-gradient(180deg, var(--sky), var(--indigo)); }
.lg-warn { background: var(--warn); }
.lg-bad { background: var(--bad); }
.chart-wrap { position: relative; height: 120px; touch-action: none; }
#chart-svg { display: block; width: 100%; height: 120px; overflow: visible; }
#chart-svg .bar { transition: opacity .15s; }
#chart-svg.hovering .bar { opacity: .35; }
#chart-svg.hovering .bar.active { opacity: 1; }
#chart-svg .grid { stroke: rgba(148, 180, 255, .08); stroke-width: 1; }
#chart-svg .limit { stroke: rgba(251, 191, 36, .7); stroke-width: 1; stroke-dasharray: 3 3; }
#chart-svg .limit-label { fill: var(--warn); font: 700 9.5px var(--font); }
#chart-svg .peak-dot { fill: var(--text); stroke: var(--bg); stroke-width: 2; }
#chart-svg .cursor { stroke: rgba(186, 230, 253, .3); stroke-width: 1; }
#chart-svg .grow { transform-origin: 0 100%; animation: grow .7s var(--ease) both; }
@keyframes grow { from { transform: scaleY(0); } }
.tip {
  position: absolute; top: -6px; transform: translate(-50%, -100%); padding: 6px 9px; border-radius: 10px; pointer-events: none;
  background: rgba(10, 20, 44, .97); border: 1px solid var(--line-2); box-shadow: 0 10px 24px rgba(0, 0, 0, .45);
  white-space: nowrap; font-size: 11px; font-variant-numeric: tabular-nums; z-index: 2;
}
.tip b { font-size: 13px; }
.tip small { display: block; color: var(--muted); font-size: 10px; }
.chart-axis { display: flex; justify-content: space-between; margin-top: 6px; color: var(--faint); font-size: 10px; font-variant-numeric: tabular-nums; }

/* ---------- Compressione ---------- */

.kv { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin: 12px 0 0; }
.kv div { padding: 8px 10px; border-radius: 12px; background: rgba(148, 180, 255, .035); border: 1px solid var(--line); min-width: 0; }
.kv dt { display: flex; align-items: center; gap: 6px; color: var(--faint); font-size: 10px; font-weight: 700; letter-spacing: .4px; text-transform: uppercase; }
.kv dt::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: #3a4a6e; }
.kv .ok dt::before { background: var(--ok); }
.kv .warn dt::before { background: var(--warn); }
.kv .bad dt::before { background: var(--bad); }
.kv dd { margin: 2px 0 0; font-weight: 650; font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tips { list-style: none; margin: 10px 0 0; padding: 0; display: grid; gap: 6px; }
.tips:empty { display: none; }
.tips li {
  position: relative; padding: 8px 10px 8px 30px; border-radius: 12px; font-size: 11.5px; color: #e3ebff;
  background: rgba(99, 102, 241, .1); border: 1px solid rgba(99, 102, 241, .24);
}
.tips li::before { content: "→"; position: absolute; left: 11px; top: 7px; color: var(--sky); font-weight: 800; }

/* ---------- Controlli ---------- */

.checks { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.checks li {
  --accent: var(--ok);
  display: grid; grid-template-columns: 22px 1fr; gap: 8px; align-items: center; padding: 8px 9px; border-radius: 12px;
  background: rgba(148, 180, 255, .035); border: 1px solid var(--line); min-width: 0;
}
.checks li.warn { --accent: var(--warn); }
.checks li.bad { --accent: var(--blue); }
.checks li.info { --accent: var(--muted); }
.checks li.wide { grid-column: 1 / -1; align-items: start; background: color-mix(in srgb, var(--accent) 8%, transparent); border-color: color-mix(in srgb, var(--accent) 26%, transparent); }
.checks .ic {
  width: 22px; height: 22px; border-radius: 8px; display: grid; place-items: center; color: var(--accent);
  background: color-mix(in srgb, var(--accent) 15%, transparent);
}
.checks .ic svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
.checks .txt { display: flex; flex-direction: column; min-width: 0; }
.checks .label { color: var(--faint); font-size: 10px; font-weight: 700; letter-spacing: .4px; text-transform: uppercase; }
.checks .value { font-weight: 650; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.checks .detail { color: var(--muted); font-size: 11.5px; margin-top: 2px; }

/* ---------- Picchi: qualità piena o limite ---------- */

.peaks { border-color: rgba(251, 191, 36, .28); background: radial-gradient(120% 80% at 100% 0%, rgba(251, 191, 36, .07), transparent 60%), var(--surface); }
.peaks-choices { display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); gap: 6px; margin-top: 12px; }
.peaks-choices button {
  display: flex; flex-direction: column; align-items: flex-start; gap: 1px; min-width: 0; padding: 9px 10px; text-align: left;
  border-radius: 12px; border: 1px solid var(--line-2); background: var(--surface-2); color: var(--muted);
  transition: border-color .2s, background .2s, color .2s, transform .2s var(--ease);
}
.peaks-choices button b { color: var(--text); font-size: 12.5px; font-weight: 750; }
.peaks-choices button small { font-size: 10.5px; line-height: 1.3; }
.peaks-choices button:hover:not(:disabled) { background: var(--surface-3); }
.peaks-choices button:active:not(:disabled) { transform: scale(.98); }
.peaks-choices button[aria-checked="true"] { border-color: var(--sky); background: rgba(56, 189, 248, .1); box-shadow: 0 0 0 3px rgba(56, 189, 248, .1); }
.peaks-choices button[aria-checked="true"] b { color: var(--sky); }
.peaks-choices button:disabled { opacity: .45; }

/* ---------- Piano: cosa succede premendo il pulsante ---------- */

.plan { border-color: rgba(59, 130, 246, .3); background: radial-gradient(120% 70% at 100% 0%, rgba(59, 130, 246, .1), transparent 60%), var(--surface); }
.time-chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 999px; white-space: nowrap;
  background: rgba(56, 189, 248, .12); color: var(--sky); font-size: 10.5px; font-weight: 750;
}
.time-chip svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.plan-steps { list-style: none; counter-reset: plan; display: grid; gap: 0; margin: 2px 0 0; padding: 0; }
.plan-steps li {
  counter-increment: plan; position: relative; display: grid; grid-template-columns: 26px 1fr; gap: 10px; padding-bottom: 11px;
  animation: rise .4s var(--ease) both;
}
.plan-steps li::before {
  content: counter(plan); display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; z-index: 1;
  background: var(--grad); color: #fff; font-size: 11px; font-weight: 800; box-shadow: 0 4px 12px rgba(59, 130, 246, .35);
}
.plan-steps li:not(:last-child)::after { content: ""; position: absolute; left: 12px; top: 26px; bottom: 1px; width: 2px; border-radius: 2px; background: linear-gradient(rgba(59, 130, 246, .5), rgba(59, 130, 246, .08)); }
.plan-steps li:last-child { padding-bottom: 0; }
.plan-steps li > div { display: flex; flex-direction: column; padding-top: 2px; min-width: 0; }
.plan-steps b { font-weight: 700; font-size: 12.5px; }
.plan-steps span { color: var(--muted); font-size: 11.5px; }
.plan-chips { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 5px; }
.plan-chips i { padding: 1px 7px; border-radius: 7px; font-style: normal; font-size: 10.5px; font-weight: 650; color: var(--muted); background: var(--surface-2); border: 1px solid var(--line); }
.plan-chips i b { color: var(--text); font-size: 10.5px; }

/* ---------- Conversione in corso ---------- */

.work-card {
  display: flex; flex-direction: column; align-items: center; padding: 18px 16px 14px;
  border-color: rgba(56, 189, 248, .3); background: radial-gradient(100% 60% at 50% 0%, rgba(56, 189, 248, .14), transparent 70%), var(--surface);
}
.work-ring { position: relative; width: 132px; height: 132px; }
.work-ring svg { width: 132px; height: 132px; transform: rotate(-90deg); }
.work-track { fill: none; stroke: rgba(148, 180, 255, .1); stroke-width: 9; }
.work-arc {
  fill: none; stroke: url(#work-g); stroke-width: 9; stroke-linecap: round; stroke-dasharray: 0 400;
  filter: drop-shadow(0 0 6px rgba(56, 189, 248, .55)); transition: stroke-dasharray .4s linear;
}
.work-ring.idle svg { animation: rot 1.2s linear infinite; }
.work-ring.idle .work-arc { stroke-dasharray: 70 400 !important; transition: none; }
.work-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.work-center b { font: 750 30px/1 var(--font-display); letter-spacing: -1px; font-variant-numeric: tabular-nums; }
.work-center small { margin-top: 4px; color: var(--muted); font-size: 11px; font-variant-numeric: tabular-nums; }
.work-steps { list-style: none; display: grid; gap: 4px; width: 100%; margin: 14px 0 0; padding: 0; }
.work-steps li {
  --c: var(--faint);
  display: grid; grid-template-columns: 22px 1fr auto; gap: 10px; align-items: center; padding: 7px 10px; border-radius: 12px;
  color: var(--faint); transition: background .3s, color .3s;
}
.work-steps li.now { --c: var(--sky); color: var(--text); background: rgba(56, 189, 248, .08); }
.work-steps li.done { --c: var(--ok); color: var(--muted); }
.work-steps .ws-ic { position: relative; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; color: var(--c); background: color-mix(in srgb, var(--c) 15%, transparent); }
.work-steps .ws-ic svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2.8; stroke-linecap: round; stroke-linejoin: round; }
.work-steps li.now .ws-ic::after { content: ""; position: absolute; inset: 0; border-radius: 50%; border: 2px solid transparent; border-top-color: var(--sky); animation: rot .8s linear infinite; }
.work-steps li:not(.done):not(.now) .ws-ic::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; }
.work-steps b { font-size: 12.5px; font-weight: 650; }
.work-steps small { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; }
.work-note { display: flex; align-items: center; gap: 7px; margin: 12px 0 0; color: #fde7a8; font-size: 11.5px; }
.work-note svg { width: 15px; height: 15px; fill: none; stroke: var(--warn); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.steps { list-style: none; counter-reset: step; margin: 12px 0; padding: 0; display: grid; gap: 0; }
.steps li { counter-increment: step; position: relative; display: grid; grid-template-columns: 26px 1fr; gap: 10px; padding-bottom: 12px; }
.steps li::before {
  content: counter(step); width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center;
  background: var(--bg-2); border: 1px solid var(--line-2); color: var(--sky); font-size: 11px; font-weight: 800; z-index: 1;
}
.steps li:not(:last-child)::after { content: ""; position: absolute; left: 12px; top: 26px; bottom: 2px; width: 1px; background: linear-gradient(var(--line-2), transparent); }
.steps li:last-child { padding-bottom: 0; }
.steps li > div { display: flex; flex-direction: column; padding-top: 2px; }
.steps b { font-weight: 700; font-size: 12.5px; }
.steps b em { font-style: normal; color: var(--sky); word-break: break-all; }
.steps span { color: var(--muted); font-size: 11.5px; }
.steps.compact { margin: 10px 0 8px; text-align: left; }
.upload-steps { width: 100%; margin: 16px 0 14px; text-align: left; }
.upload-steps li::before { background: linear-gradient(135deg, rgba(56, 189, 248, .25), rgba(99, 102, 241, .25)); border-color: rgba(56, 189, 248, .4); color: #fff; }
.hb-alt { margin-top: 12px; border-top: 1px solid var(--line); border-radius: 0; padding-top: 4px; }
.hint { margin: 6px 2px 0; color: var(--faint); font-size: 11px; }

/* ---------- Pulsanti ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 40px; padding: 9px 14px;
  border-radius: 13px; border: 1px solid var(--line-2); background: var(--surface-2); font-weight: 700;
  transition: transform .2s var(--ease), background .2s, filter .2s, box-shadow .2s;
}
.btn svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.btn:hover:not(:disabled) { background: var(--surface-3); }
.btn:active:not(:disabled) { transform: scale(.98); }
.btn:disabled { opacity: .45; }
.btn.primary { border-color: transparent; color: #fff; background: linear-gradient(100deg, var(--sky), var(--blue)); box-shadow: 0 8px 22px rgba(59, 130, 246, .3); }
.btn.primary:hover:not(:disabled) { filter: brightness(1.08); background: linear-gradient(100deg, var(--sky), var(--blue)); box-shadow: 0 10px 28px rgba(59, 130, 246, .42); }
.btn.ghost { background: transparent; color: var(--muted); }
.btn.ghost:hover:not(:disabled) { color: var(--text); }

.cta {
  --p: 0;
  position: relative; isolation: isolate; overflow: hidden; display: flex; align-items: center; justify-content: center; gap: 10px;
  width: 100%; height: 54px; border: 0; border-radius: 17px; color: #fff; font: 750 15px/1 var(--font-display); letter-spacing: -.1px;
  background: var(--grad); background-size: 160% 100%; box-shadow: 0 14px 34px rgba(59, 130, 246, .38), 0 1px 0 rgba(255, 255, 255, .35) inset;
  transition: transform .25s var(--ease), box-shadow .25s, background-position .6s var(--ease);
}
.cta svg { width: 19px; height: 19px; fill: #fff; position: relative; z-index: 2; }
.cta > span:last-child { position: relative; z-index: 2; text-shadow: 0 1px 8px rgba(2, 8, 30, .3); }
.cta:hover:not(:disabled) { transform: translateY(-1px); background-position: 100% 0; box-shadow: 0 18px 40px rgba(59, 130, 246, .5), 0 1px 0 rgba(255, 255, 255, .35) inset; }
.cta:active:not(:disabled) { transform: scale(.985); }
.cta:disabled { cursor: default; }
.cta-shine {
  position: absolute; inset: 0; z-index: 1; pointer-events: none;
  background: linear-gradient(105deg, transparent 35%, rgba(255, 255, 255, .45) 50%, transparent 65%); transform: translateX(-120%);
  animation: shine 3.2s ease-in-out 1s infinite;
}
@keyframes shine { 0%, 60% { transform: translateX(-120%); } 100% { transform: translateX(120%); } }
.cta-fill { position: absolute; inset: 0; z-index: 1; background: rgba(4, 10, 30, .55); transform-origin: right; transform: scaleX(calc(1 - var(--p))); opacity: 0; transition: transform .2s linear, opacity .2s; }
.cta.working .cta-fill { opacity: 1; }
.cta.working .cta-shine { display: none; }
.status { margin: -2px 2px 0; color: var(--muted); font-size: 11.5px; white-space: pre-line; }
.status:empty { display: none; }
.status.bad { color: var(--bad); }
.status.ok { color: var(--ok); }

/* ---------- Barra in basso: il pulsante da premere è sempre qui ---------- */

.dock {
  position: sticky; bottom: 0; z-index: 6; display: grid; gap: 7px; margin: 12px -14px -12px; padding: 18px 14px 12px;
  background: linear-gradient(180deg, rgba(5, 10, 24, 0), rgba(5, 10, 24, .9) 26%, rgba(5, 10, 24, .97));
}
.dock .status { margin: 0 2px; text-align: center; }
.dock-row { display: grid; grid-template-columns: 1.4fr 1fr; gap: 8px; }
.btn.tall { min-height: 54px; border-radius: 17px; font-size: 13.5px; }
.cta.pop { animation: ctapop .5s var(--ease); }
@keyframes ctapop { from { transform: translateY(8px) scale(.97); opacity: .4; } }

/* ---------- Pronto da caricare ---------- */

.done {
  position: relative; overflow: hidden; display: flex; flex-direction: column; align-items: center; text-align: center; padding: 22px 16px 12px;
  border-color: rgba(52, 211, 153, .3); background: radial-gradient(100% 60% at 50% 0%, rgba(52, 211, 153, .14), transparent 70%), var(--surface);
}
.done-check svg { width: 58px; height: 58px; fill: none; stroke: var(--ok); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }
.done-check circle { stroke-dasharray: 145; stroke-dashoffset: 145; animation: draw .7s var(--ease) forwards; opacity: .45; }
.done-check path { stroke-dasharray: 40; stroke-dashoffset: 40; animation: draw .45s var(--ease) .45s forwards; }
@keyframes draw { to { stroke-dashoffset: 0; } }
.done > strong { margin-top: 8px; font: 750 18px/1.2 var(--font-display); }
.done-file { color: var(--muted); font-size: 11.5px; margin-top: 2px; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.done-meta { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; width: 100%; margin-top: 14px; }
.done-meta span, .md5 { display: flex; flex-direction: column; align-items: flex-start; padding: 8px 11px; border-radius: 12px; background: rgba(148, 180, 255, .04); border: 1px solid var(--line); }
.done-meta small, .md5 small { color: var(--faint); font-size: 10px; font-weight: 700; letter-spacing: .4px; text-transform: uppercase; }
.done-meta b { font-size: 13px; font-variant-numeric: tabular-nums; }
.md5 { position: relative; width: 100%; margin-top: 8px; text-align: left; transition: background .2s, border-color .2s; }
.md5:hover { background: var(--surface-2); border-color: var(--line-2); }
.md5 code { font: 600 11.5px/1.4 var(--mono); color: var(--sky); letter-spacing: .3px; word-break: break-all; padding-right: 22px; }
.md5 svg { position: absolute; right: 10px; top: 50%; width: 15px; height: 15px; transform: translateY(-50%); fill: none; stroke: var(--muted); stroke-width: 1.8; }
.md5.copied { border-color: rgba(52, 211, 153, .4); }
.md5.copied small::after { content: " · copied"; color: var(--ok); }
.burst { position: absolute; left: 50%; top: 50px; width: 0; height: 0; pointer-events: none; }
.burst i { position: absolute; width: 6px; height: 6px; border-radius: 2px; opacity: 0; animation: confetti 1.1s var(--ease) forwards; }
@keyframes confetti {
  0% { opacity: 1; transform: translate(0, 0) rotate(0); }
  100% { opacity: 0; transform: translate(var(--x), var(--y)) rotate(var(--r)); }
}

/* ---------- Verifica ---------- */

.verify-hero {
  position: relative; display: flex; flex-direction: column; align-items: center; text-align: center; padding: 20px 16px 16px;
  border-radius: 22px; background: radial-gradient(120% 90% at 50% 0%, rgba(59, 130, 246, .18), transparent 65%), var(--surface); border: 1px solid var(--line);
}
.shield {
  display: grid; place-items: center; width: 62px; height: 62px; border-radius: 20px; margin-bottom: 10px;
  background: linear-gradient(145deg, rgba(56, 189, 248, .2), rgba(99, 102, 241, .24)); box-shadow: 0 0 0 1px rgba(186, 230, 253, .1) inset, 0 14px 34px rgba(59, 130, 246, .25);
}
.shield svg { width: 36px; height: 36px; fill: none; stroke: var(--text); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.shield path:last-child { stroke: var(--sky); }
.verify-hero > p { margin: 0 0 14px; color: var(--muted); font-size: 12px; }
.link-field {
  position: relative; display: flex; align-items: center; width: 100%; height: 46px; padding: 0 5px 0 12px; gap: 8px; border-radius: 14px;
  background: rgba(2, 6, 20, .45); border: 1px solid var(--line-2); transition: border-color .2s, box-shadow .2s;
}
.link-field:focus-within { border-color: rgba(56, 189, 248, .6); box-shadow: 0 0 0 4px rgba(56, 189, 248, .12); }
.link-field > svg { width: 17px; height: 17px; fill: none; stroke: var(--faint); stroke-width: 2; stroke-linecap: round; }
.link-field input { flex: 1; min-width: 0; height: 100%; border: 0; outline: 0; background: none; font-size: 12.5px; }
.link-field input::placeholder { color: var(--faint); }
.go {
  display: grid; place-items: center; width: 36px; height: 36px; border: 0; border-radius: 10px;
  background: linear-gradient(135deg, var(--sky), var(--indigo)); color: #fff; transition: transform .2s var(--ease), filter .2s;
}
.go:hover { filter: brightness(1.1); transform: translateX(1px); }
.go svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.verify-hero .hint { margin-top: 8px; }
.verify-hero .hint.bad { color: var(--bad); }

.mini-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 10px; }
.mini-stats span { display: flex; flex-direction: column; padding: 9px 11px; border-radius: 14px; background: var(--surface); border: 1px solid var(--line); color: var(--faint); font-size: 10.5px; font-weight: 650; }
.mini-stats b { font: 750 19px/1.1 var(--font-display); color: var(--text); font-variant-numeric: tabular-nums; }
.mini-stats .ok b { color: var(--ok); }
.mini-stats .warn b { color: var(--warn); }

.section-title { margin: 18px 2px 8px; color: var(--faint); font-size: 10.5px; font-weight: 800; letter-spacing: .9px; text-transform: uppercase; }
.list { list-style: none; margin: 0; padding: 0; display: grid; gap: 7px; }
.list li {
  --accent: #3a4a6e;
  display: grid; grid-template-columns: 34px 1fr auto; gap: 10px; align-items: center; padding: 10px; border-radius: 15px;
  background: var(--surface); border: 1px solid var(--line); animation: rise .35s var(--ease) both;
}
.list li.perfect { --accent: var(--ok); }
.list li.partial, .list li.different, .list li.unknown { --accent: var(--warn); }
.list li.recompressed { --accent: var(--bad); }
.list li.file { --accent: var(--blue); }
.list .ic {
  width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; color: var(--accent);
  background: color-mix(in srgb, var(--accent) 15%, transparent); border: 1px solid color-mix(in srgb, var(--accent) 28%, transparent);
}
.list .ic svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.list .body { display: flex; flex-direction: column; min-width: 0; gap: 2px; }
.list .title { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.list .sub { color: var(--faint); font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.list .tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 2px; }
.list .tags span { padding: 1px 6px; border-radius: 6px; font-size: 10px; font-weight: 700; background: var(--surface-2); color: var(--muted); }
.list .tags span.accent { color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent); }
.empty { margin: 0; padding: 14px; border-radius: 15px; border: 1px dashed var(--line-2); color: var(--faint); font-size: 11.5px; text-align: center; }

/* ---------- Impostazioni ---------- */

.sheet { position: fixed; inset: 0; z-index: 20; display: flex; align-items: flex-end; }
.sheet-backdrop { position: absolute; inset: 0; background: rgba(2, 6, 18, .6); backdrop-filter: blur(3px); animation: fade .25s; }
@keyframes fade { from { opacity: 0; } }
.sheet-card {
  position: relative; width: 100%; max-width: 480px; margin: 0 auto; padding: 14px 14px 16px; border-radius: 22px 22px 0 0;
  background: linear-gradient(180deg, #0f1d3a, #081022); border: 1px solid var(--line-2); border-bottom: 0;
  box-shadow: 0 -20px 50px rgba(0, 0, 0, .5); animation: up .35s var(--ease);
}
@keyframes up { from { transform: translateY(100%); } }
.sheet-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.sheet-head strong { font: 750 15px var(--font-display); }
.setting { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 11px 12px; margin-bottom: 7px; border-radius: 14px; background: var(--surface); border: 1px solid var(--line); cursor: pointer; }
.setting > span:first-child { display: flex; flex-direction: column; }
.setting strong { font-weight: 650; }
.setting > span:first-child > span { color: var(--muted); font-size: 11.5px; margin-top: 1px; }
.switch { position: relative; flex: none; width: 40px; height: 24px; }
.switch input { position: absolute; inset: 0; opacity: 0; margin: 0; cursor: pointer; }
.switch i { position: absolute; inset: 0; border-radius: 12px; background: #1e2a48; transition: background .25s; pointer-events: none; }
.switch i::after { content: ""; position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #fff; box-shadow: 0 2px 6px rgba(0, 0, 0, .35); transition: transform .3s var(--ease); }
.switch input:checked + i { background: linear-gradient(90deg, var(--sky), var(--blue)); }
.switch input:checked + i::after { transform: translateX(16px); }
.switch input:focus-visible + i { outline: 2px solid var(--sky); outline-offset: 2px; }
.sheet-note { margin: 8px 2px 0; color: var(--faint); font-size: 11px; }

.foot { display: flex; align-items: center; justify-content: center; gap: 6px; margin: 16px 0 0; color: var(--faint); font-size: 11px; }
.foot svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; }

/* ---------- Spiegazioni in parole semplici ---------- */

.helper, .caption {
  display: grid; grid-template-columns: 16px 1fr; gap: 8px; align-items: start; margin: 12px 0 0; padding: 9px 11px;
  border-radius: 13px; color: var(--muted); font-size: 11.5px; line-height: 1.45;
  background: rgba(148, 180, 255, .04); border: 1px solid var(--line);
}
.caption { margin: -2px 0 0; padding: 7px 10px; }
.helper svg, .caption svg { width: 16px; height: 16px; margin-top: 1px; fill: none; stroke: var(--sky); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.helper b, .caption b { color: var(--text); font-weight: 700; }

.key-checks .kc-label { display: flex; flex-direction: column; min-width: 0; color: var(--text); font-size: 12.5px; font-weight: 650; }
.key-checks .kc-label small { color: var(--faint); font-size: 11px; font-weight: 500; line-height: 1.35; }
.key-checks li.fix .kc-label small { color: #8fcdf3; }
.key-checks li.warn .kc-label small { color: #e9cf8b; }
.key-checks li { align-items: start; }
.key-checks .kc-ic { margin-top: 1px; }
.key-checks .kc-value { padding-top: 1px; }

.upload-lead { align-self: stretch; margin: 16px 2px -4px; text-align: left; color: var(--faint); font-size: 10.5px; font-weight: 800; letter-spacing: .9px; text-transform: uppercase; }

.legend-card { margin-top: 10px; }
.legend-card > strong { font-size: 12.5px; }
.result-legend { list-style: none; display: grid; gap: 8px; margin: 10px 0 2px; padding: 0; }
.result-legend li { --c: var(--ok); display: grid; grid-template-columns: 24px 1fr; gap: 10px; align-items: start; }
.result-legend li.warn { --c: var(--warn); }
.result-legend li.bad { --c: var(--bad); }
.rl-ic { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; color: var(--c); background: color-mix(in srgb, var(--c) 15%, transparent); }
.rl-ic svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
.result-legend li > span:last-child { display: flex; flex-direction: column; color: var(--muted); font-size: 11.5px; }
.result-legend b { color: var(--text); font-size: 12.5px; }

/* ---------- Come funziona ---------- */

.help-card { max-height: 92vh; overflow-y: auto; }
.help-steps { list-style: none; counter-reset: help; display: grid; gap: 10px; margin: 4px 0 0; padding: 0; }
.help-steps li { counter-increment: help; display: grid; grid-template-columns: 26px 1fr; column-gap: 10px; }
.help-steps li::before {
  content: counter(help); grid-row: span 2; display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%;
  background: var(--grad); color: #fff; font-size: 11px; font-weight: 800;
}
.help-steps b { font-size: 12.5px; }
.help-steps span { color: var(--muted); font-size: 11.5px; }
.help-sub { margin: 16px 2px 8px; color: var(--faint); font-size: 10.5px; font-weight: 800; letter-spacing: .9px; text-transform: uppercase; }
.glossary { display: grid; gap: 6px; margin: 0; }
.glossary div { display: grid; grid-template-columns: 96px 1fr; gap: 10px; padding: 8px 10px; border-radius: 12px; background: var(--surface); border: 1px solid var(--line); }
.glossary dt { color: var(--sky); font-weight: 750; font-size: 12px; }
.glossary dd { margin: 0; color: var(--muted); font-size: 11.5px; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

