// Validazione HQ e adattatore per il patcher WTM 2.0.6, invariato in wtm-patcher.js.
(() => {
  "use strict";
  const containers = new Set(["moov", "trak", "mdia", "minf", "stbl"]);
  function inspect(input) {
    const b = input instanceof Uint8Array ? input : new Uint8Array(input);
    const view = new DataView(b.buffer, b.byteOffset, b.byteLength);
    const u32 = o => {
      if (o < 0 || o + 4 > b.length) throw new Error("Truncated MP4 file.");
      return view.getUint32(o);
    };
    const type = o => String.fromCharCode(...b.subarray(o, o + 4));
    function parse(start, end, depth = 0) {
      if (depth > 32) throw new Error("MP4 structure nested too deeply.");
      const out = [];
      for (let p = start; p < end;) {
        if (p + 8 > end) throw new Error("Truncated MP4 header.");
        let size = u32(p), header = 8;
        if (size === 1) { size = u32(p + 8) * 4294967296 + u32(p + 12); header = 16; }
        if (size === 0) size = end - p;
        if (!Number.isSafeInteger(size) || size < header || p + size > end) throw new Error("Invalid MP4 box size.");
        const kind = type(p + 4), box = {kind, data: p + header, end: p + size};
        if (containers.has(kind)) box.children = parse(box.data, box.end, depth + 1);
        out.push(box); p += size;
      }
      return out;
    }
    const top = parse(0, b.length), moovs = top.filter(x => x.kind === "moov");
    if (moovs.length !== 1 || top.filter(x => x.kind === "mdat").length !== 1 || top.some(x => ["moof", "sidx"].includes(x.kind)) || moovs[0].children.some(x => x.kind === "mvex")) {
      throw new Error("This needs a non-fragmented MP4 with a single moov and a single mdat.");
    }
    if (!top.some(x => x.kind === "ftyp")) throw new Error("Not a valid MP4: ftyp is missing.");
    const mvhd = moovs[0].children.find(x => x.kind === "mvhd");
    if (!mvhd) throw new Error("The movie header is missing.");
    const version = b[mvhd.data], start = mvhd.data + (version === 1 ? 24 : 16), end = start + (version === 1 ? 8 : 4);
    if (![0, 1].includes(version) || end > mvhd.end) throw new Error("The movie header is invalid.");
    const unknownDuration = b.subarray(start, end).every(x => x === 255);
    const info = globalThis.WtmMp4Patcher.inspect(b);
    const child = (x, kind) => x?.children?.find(y => y.kind === kind);
    const video = moovs[0].children.find(x => {
      const hdlr = child(child(x, "mdia"), "hdlr");
      return x.kind === "trak" && hdlr && hdlr.data + 12 <= hdlr.end && type(hdlr.data + 8) === "vide";
    });
    const stsz = child(child(child(child(video, "mdia"), "minf"), "stbl"), "stsz");
    const declared = stsz && stsz.data + 12 <= stsz.end ? u32(stsz.data + 8) : info.realSamples;
    if (!(info.duration > 0) || !(info.width > 0) || !(info.height > 0)) throw new Error("Invalid video size or duration.");
    return {...info, seconds: info.duration, bitrate: info.bitrateBps, samples: info.realSamples,
      alreadyPatched: unknownDuration || declared !== info.realSamples,
      patchKind: unknownDuration ? "wtm206" : declared !== info.realSamples ? "legacy-ghosts" : null};
  }
  function patch(input) {
    if (inspect(input).alreadyPatched) throw new Error("This file is already prepared. Pick the original video, without the patch.");
    return globalThis.WtmMp4Patcher.patch(input);
  }
  globalThis.HQPatcher = Object.freeze({inspect, patch});
})();

