// MD5 incrementale (RFC 1321). TikTok dichiara l'MD5 del file conservato:
// confrontarlo con quello calcolato qui dice se il file su TikTok è il tuo.
// Script classico: lo usano sia il popup sia lo script di verifica sul player.
(() => {
  "use strict";
  if (globalThis.HQMd5) return;
  const S = [7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21];
  const K = new Int32Array(64);
  for (let i = 0; i < 64; i++) K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) | 0;

  function create() {
    const state = new Int32Array([0x67452301, 0xefcdab89 | 0, 0x98badcfe | 0, 0x10325476]);
    const block = new Uint8Array(64);
    const words = new Int32Array(16);
    let used = 0;
    let length = 0;

    function compress(bytes, offset) {
      for (let i = 0; i < 16; i++) {
        const o = offset + i * 4;
        words[i] = bytes[o] | bytes[o + 1] << 8 | bytes[o + 2] << 16 | bytes[o + 3] << 24;
      }
      let a = state[0], b = state[1], c = state[2], d = state[3];
      for (let i = 0; i < 64; i++) {
        let f, g;
        if (i < 16) { f = (b & c) | (~b & d); g = i; }
        else if (i < 32) { f = (d & b) | (~d & c); g = (5 * i + 1) & 15; }
        else if (i < 48) { f = b ^ c ^ d; g = (3 * i + 5) & 15; }
        else { f = c ^ (b | ~d); g = (7 * i) & 15; }
        const sum = (a + f + K[i] + words[g]) | 0;
        a = d; d = c; c = b;
        b = (b + (sum << S[i] | sum >>> (32 - S[i]))) | 0;
      }
      state[0] += a; state[1] += b; state[2] += c; state[3] += d;
    }

    return {
      update(input) {
        const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
        length += bytes.length;
        let i = 0;
        if (used) {
          const take = Math.min(64 - used, bytes.length);
          block.set(bytes.subarray(0, take), used);
          used += take; i = take;
          if (used < 64) return this;
          compress(block, 0);
          used = 0;
        }
        for (; i + 64 <= bytes.length; i += 64) compress(bytes, i);
        if (i < bytes.length) { block.set(bytes.subarray(i), 0); used = bytes.length - i; }
        return this;
      },
      digest() {
        const bits = length * 8;
        const tail = new Uint8Array((used < 56 ? 64 : 128) - used);
        tail[0] = 0x80;
        const view = new DataView(tail.buffer);
        view.setUint32(tail.length - 8, bits >>> 0, true);
        view.setUint32(tail.length - 4, Math.floor(bits / 4294967296), true);
        this.update(tail);
        let hex = "";
        for (let i = 0; i < 4; i++) {
          for (let j = 0; j < 4; j++) hex += ((state[i] >>> (8 * j)) & 255).toString(16).padStart(2, "0");
        }
        return hex;
      },
    };
  }

  // Calcolo a blocchi: lascia respirare l'interfaccia sui file grandi.
  async function hash(input, onProgress = () => {}) {
    const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
    const md5 = create();
    const step = 8 * 1024 * 1024;
    for (let i = 0; i < bytes.length; i += step) {
      md5.update(bytes.subarray(i, Math.min(bytes.length, i + step)));
      onProgress(Math.min(1, (i + step) / bytes.length));
      await new Promise((resolve) => setTimeout(resolve, 0));
    }
    return md5.digest();
  }

  globalThis.HQMd5 = Object.freeze({ create, hash });
})();

