import { evaluate, originalPlan, prepareOriginalVideo, PEAK_HIGH, PEAK_OK } from "./original.js";
import { analyzeVideo } from "./analysis.js";
import { assessCompression, detectEncoder } from "./encoder.js";
import { handbrakePreset, handbrakeSteps } from "./handbrake.js";
import { x264Ready } from "./x264.js";

(() => {
  "use strict";

  const $ = (id) => document.getElementById(id);
  const NS = "http://www.w3.org/2000/svg";
  const PREPARED_KEY = "hqupPrepared";
  const CHECKS_KEY = "hqupChecks";
  // Il guscio passa all'avvio dove gira l'app (popup o scheda) e i parametri della sua pagina.
  const context = window.HQ_CONTEXT || {};
  const params = new URLSearchParams(context.search || "");
  const inTab = !!context.inTab;
  const canCompress = x264Ready();
  const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const fileInput = $("file");
  const drop = $("drop");
  const report = $("report");
  const cta = $("run-original");
  const toggle = $("request-toggle");
  const verifyBytes = $("verify-bytes");

  const nf = (value, digits = 1) => value.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
  const formatMB = (bytes) => nf(bytes / 1e6);
  const round = (value) => Math.round(value * 100) / 100;
  const clock = (seconds) => `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, "0")}`;
  // In una scheda in secondo piano requestAnimationFrame non arriva: il timeout evita che il lavoro resti fermo.
  const nextFrame = () => new Promise((resolve) => {
    requestAnimationFrame(() => setTimeout(resolve, 0));
    setTimeout(resolve, 120);
  });
  const storage = {
    get: (keys) => new Promise((resolve) => chrome.storage.local.get(keys, resolve)),
    set: (value) => new Promise((resolve) => chrome.storage.local.set(value, resolve)),
  };

  let current = null; // { file, info, analysis, evaluation, encoder, source: { file, info, analysis, force60 } }
  let busy = false;
  let peakChoice = null; // null = qualità piena, altrimenti limite in Mbps
  let pending = null; // file appena convertito in attesa della scelta sui picchi
  let selectionId = 0;
  let thumbUrl = null;

  if (inTab) {
    document.body.classList.add("tab");
    $("open-tab").hidden = true;
  }

  // ---------- Elementi ----------

  const ICON = {
    check: '<path d="M5 12.5l4.2 4.2L19 7"/>',
    alert: '<path d="M12 6.5v7"/><path d="M12 17.5h.01"/>',
    cross: '<path d="M7 7l10 10M17 7L7 17"/>',
    info: '<path d="M12 11v6"/><path d="M12 7h.01"/>',
    bolt: '<path d="M13 3L5 13.5h6L10 21l8-10.5h-6z"/>',
    arrow: '<path d="M5 12h14M13 6l6 6-6 6"/>',
    clock: '<circle cx="12" cy="12" r="8"/><path d="M12 8v4l2.5 2"/>',
    question: '<path d="M9.3 9.2a2.7 2.7 0 1 1 3.9 2.4c-.7.4-1.2 1-1.2 1.8v.6"/><path d="M12 17.5h.01"/>',
    refresh: '<path d="M19.5 10.5A7.5 7.5 0 0 0 6.2 7.2L4.5 9"/><path d="M4.5 4.5V9H9"/><path d="M4.5 13.5a7.5 7.5 0 0 0 13.3 3.3l1.7-1.8"/><path d="M19.5 19.5V15H15"/>',
    film: '<rect x="4" y="5" width="16" height="14" rx="3"/><path d="M10.2 9.5v5l4.2-2.5z"/>',
    upload: '<path d="M12 15V4M7.5 8.5L12 4l4.5 4.5M5 15v3.5A1.5 1.5 0 0 0 6.5 20h11a1.5 1.5 0 0 0 1.5-1.5V15"/>',
    shield: '<path d="M12 3l7.5 3v5.5c0 4.6-3.1 8-7.5 9.5-4.4-1.5-7.5-4.9-7.5-9.5V6z"/><path d="M8.8 12l2.2 2.2 4.3-4.4"/>',
    sparkle: '<path d="M12 3l1.9 4.6L18.5 9.5l-4.6 1.9L12 16l-1.9-4.6L5.5 9.5l4.6-1.9z"/><path d="M18.5 15.5l.8 1.9 1.9.8-1.9.8-.8 1.9-.8-1.9-1.9-.8 1.9-.8z"/>',
  };
  const STATE_ICON = { ok: "check", warn: "alert", bad: "cross", info: "info" };

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function svgEl(tag, attrs = {}) {
    const node = document.createElementNS(NS, tag);
    for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));
    return node;
  }

  function icon(name) {
    const node = svgEl("svg", { viewBox: "0 0 24 24", "aria-hidden": "true" });
    node.innerHTML = ICON[name];
    return node;
  }

  // "Press **Prepare**" → testo con le parti tra ** in grassetto, senza innerHTML.
  function rich(node, text) {
    node.replaceChildren(...String(text).split("**").map((part, i) => i % 2 ? el("b", "", part) : document.createTextNode(part)));
  }

  function countTo(node, value, digits = 1) {
    if (reduceMotion || !Number.isFinite(value)) {
      node.textContent = Number.isFinite(value) ? nf(value, digits) : "–";
      return;
    }
    const start = performance.now();
    const step = (now) => {
      const k = Math.min(1, (now - start) / 750);
      node.textContent = nf(value * (1 - Math.pow(1 - k, 3)), digits);
      if (k < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  // ---------- Guida ----------

  // Quattro passi: video → controllo → caricamento → verifica. La guida riparte da capo a ogni apertura;
  // il titolo della schermata dice sempre, in una frase, cosa fare adesso, e il pulsante da premere sta
  // sempre nella barra in basso.
  const STEPS = ["drop", "check", "upload", "verify"];
  // Come è stato fatto il video: detected (preset HQ riconosciuto nel file) | preset (lo dice l'utente)
  // | master (export originale, da comprimere qui) | other (compresso in altro modo, usato comunque).
  let origin = null;
  let retryFile = null; // file compresso in altro modo: si chiede il master, ma resta usabile
  let guideStep = "drop";
  let guideCoach = null;
  let dockMode = "none";

  function paintStepper(name) {
    const index = STEPS.indexOf(name);
    const stepper = $("stepper");
    stepper.dataset.step = name;
    stepper.style.setProperty("--done", String(index));
    for (const li of stepper.children) {
      const i = STEPS.indexOf(li.dataset.step);
      li.className = i < index ? "past" : i === index ? "now" : "";
      const button = li.querySelector("button");
      // Si può tornare al video, ma non nel mezzo di una conversione.
      button.disabled = busy || i >= index || !button.dataset.go;
      if (i === index) button.setAttribute("aria-current", "step");
      else button.removeAttribute("aria-current");
    }
  }

  const COACH_ICON = { "": "sparkle", ok: "check", warn: "alert", bad: "cross", work: "bolt" };

  function showCoach([title, text, tone = ""]) {
    const box = $("coach");
    const changed = $("coach-title").textContent !== title;
    $("coach-title").textContent = title;
    rich($("coach-text"), text);
    box.className = `coach ${tone === "work" ? "" : tone}`;
    const badge = $("coach-icon");
    badge.className = `coach-icon${tone === "work" ? " spin" : ""}`;
    const symbol = icon(COACH_ICON[tone] || "sparkle");
    if (!tone) symbol.classList.add("fill");
    badge.replaceChildren(symbol);
    if (changed && !reduceMotion) {
      void box.offsetWidth;
      box.classList.add("pulse");
    }
  }

  function coach(title, text, tone = "") {
    guideCoach = [title, text, tone];
    if ($("panel-prepare").hidden) return;
    showCoach(guideCoach);
  }

  // none | cta (prepara/converti) | upload (TikTok Studio + "I've posted it")
  function setDock(mode) {
    dockMode = mode;
    const visible = mode !== "none" && !$("panel-prepare").hidden;
    $("action").hidden = !visible;
    const show = (id, on) => {
      const node = $(id);
      if (on && node.hidden && !reduceMotion) {
        node.classList.remove("pop");
        void node.offsetWidth;
        node.classList.add("pop");
      }
      node.hidden = !on;
    };
    show("run-original", mode === "cta");
    show("dock-upload", mode === "upload");
  }

  function goStep(name) {
    guideStep = name;
    paintStepper(name);
    $("intro").hidden = name !== "drop";
    report.hidden = name !== "check" && name !== "upload";
    setDock(name === "check" ? "cta" : name === "upload" ? "upload" : "none");
  }

  function dropGuide() {
    goStep("drop");
    $("use-anyway").hidden = !retryFile;
    // Prima ancora del video: la strada consigliata è il master compresso in HandBrake con il preset HQ;
    // in alternativa si trascina il master e lo comprime HQ Upload.
    if (retryFile) {
      $("drop-title").textContent = "Drop the master here";
      $("drop-sub").replaceChildren(document.createTextNode("The file your editing app exported · or "), el("u", "", "click to choose it"));
      $("use-anyway-name").textContent = retryFile.name;
      coach("Please start from the master instead.",
        "Compressing a video twice costs quality. Take the file your editing app exported (After Effects, Premiere, CapCut…) and compress it with HandBrake and the preset below, or drop it here: **I'll compress it for you**.", "warn");
    } else {
      $("drop-title").textContent = "Drop your video here";
      $("drop-sub").replaceChildren(document.createTextNode("HandBrake export or master · or "), el("u", "", "click to choose it"));
      coach("First, compress your master with HandBrake.",
        "Follow the 3 steps below, then drop the result. No HandBrake? Drop the master instead: **I'll compress it for you**.");
    }
  }

  // ---------- Stato ----------

  function say(text, kind = "") {
    const status = $("status");
    status.textContent = text;
    status.className = "status " + kind;
  }

  function setWorking(on, label = "", value = null) {
    cta.classList.toggle("working", on);
    cta.style.setProperty("--p", String(Math.max(0, Math.min(1, value ?? 0))));
    if (on) {
      setDock("cta");
      $("run-original-label").textContent = label;
    }
  }

  function updateControls() {
    cta.disabled = busy || !current;
    $("hb-preset").disabled = !current;
    for (const button of $("peaks-choices").children) button.disabled = busy;
    fileInput.disabled = busy;
    $("file-clear").disabled = busy;
    document.querySelector("main").setAttribute("aria-busy", String(busy));
    hq.call("setBusy", [busy && cta.classList.contains("working")]);
    paintStepper($("panel-prepare").hidden ? "verify" : guideStep);
  }

  function ring(checks) {
    const svg = $("ring-svg");
    const r = 30, c = 2 * Math.PI * r;
    const nodes = [svgEl("circle", { cx: 36, cy: 36, r, class: "track" })];
    if (!checks) {
      nodes.push(svgEl("circle", { cx: 36, cy: 36, r, class: "spinner", "stroke-dasharray": `${c * 0.22} ${c}` }));
      svg.replaceChildren(...nodes);
      return;
    }
    const n = checks.length;
    const gap = n > 1 ? 8 : 0;
    const length = c / n - gap;
    const arcs = checks.map((check, i) => {
      const arc = svgEl("circle", { cx: 36, cy: 36, r, class: `seg-arc ${check.state}` });
      arc.style.strokeDasharray = `0 ${c}`;
      arc.style.strokeDashoffset = String(-(i * c / n + gap / 2));
      arc.style.transitionDelay = `${i * 70}ms`;
      return arc;
    });
    svg.replaceChildren(...nodes, ...arcs);
    requestAnimationFrame(() => requestAnimationFrame(() => {
      for (const arc of arcs) arc.style.strokeDasharray = `${length} ${c - length}`;
    }));
  }

  function setVerdict(kind, kicker, title, sub, checks = null) {
    $("verdict").className = `verdict ${kind}`;
    $("verdict-kicker").textContent = kicker;
    $("verdict-title").textContent = title;
    $("verdict-sub").textContent = sub;
    if (kind === "busy") {
      ring(null);
      $("ring-icon").replaceChildren();
      $("key-checks").hidden = true;
      return;
    }
    const state = kind === "ready" ? "ok" : kind === "warn" ? "warn" : "bad";
    ring(checks || [{ state }]);
    $("ring-icon").replaceChildren(icon(kind === "ready" ? "check" : kind === "warn" ? "alert" : kind === "needs-fix" ? "bolt" : "cross"));
  }

  function reset() {
    selectionId++;
    current = null;
    pending = null;
    peakChoice = null;
    if (thumbUrl) URL.revokeObjectURL(thumbUrl);
    thumbUrl = null;
    const video = $("thumb");
    video.removeAttribute("src");
    video.load();
    $("thumb-box").classList.remove("ready");
    $("thumb-dur").textContent = "";
    $("file-chips").replaceChildren();
    origin = null;
    for (const id of ["chart", "compression", "profile", "origin", "plan", "hb-alt", "peaks", "working", "done", "stats-note", "stats-caption", "details", "key-checks"]) $(id).hidden = true;
    $("details").open = false;
    $("verdict").hidden = false;
    $("stats").hidden = false;
    $("stats").classList.add("loading");
    for (const id of ["stat-min", "stat-avg", "stat-peak"]) {
      $(id).className = "stat";
      $(id).querySelector(".stat-value").textContent = "–";
      $(id).querySelector(".stat-sub").textContent = "Mbps";
    }
    $("checks").replaceChildren();
    fileInput.value = "";
    say("");
    setWorking(false);
    dropGuide();
    updateControls();
  }

  // ---------- Rapporto sul file ----------

  function showFile(file) {
    goStep("check");
    $("file-name").textContent = file.name;
    $("file-name").title = file.name;
    $("file-meta").textContent = `${formatMB(file.size)} MB`;
    thumbUrl = URL.createObjectURL(file);
    const video = $("thumb");
    const box = $("thumb-box");
    video.onloadeddata = () => box.classList.add("ready");
    video.onloadedmetadata = () => { try { video.currentTime = Math.min(0.04, video.duration || 0); } catch {} };
    video.onerror = () => box.classList.remove("ready");
    video.src = thumbUrl;
    box.onmouseenter = () => { if (box.classList.contains("ready")) video.play().catch(() => {}); };
    box.onmouseleave = () => { video.pause(); try { video.currentTime = 0.04; } catch {} };
  }

  function renderStats(analysis, evaluation) {
    const stats = $("stats");
    stats.classList.remove("loading");
    if (!analysis) {
      stats.hidden = true;
      return;
    }
    const tile = (id, value, cls, title) => {
      const node = $(id);
      node.className = `stat ${cls}`;
      node.title = title;
      countTo(node.querySelector(".stat-value"), value);
      const sub = node.querySelector(".stat-sub");
      sub.replaceChildren(document.createTextNode("Mbps · "), el("b", "", `${nf(value / 8)} MB/s`));
    };
    const peak = analysis.peakMbps;
    tile("stat-min", analysis.minMbps, "cool", `The lightest second: ${nf(analysis.minMbps)} Mbps at ${analysis.minAt} s.`);
    const average = evaluation.checks.find((check) => check.id === "average");
    tile("stat-avg", analysis.averageMbps, average?.state === "warn" ? "warn" : "ok", "Average over the whole video, audio included.");
    tile("stat-peak", peak, peak <= PEAK_OK ? "ok" : peak <= PEAK_HIGH ? "warn" : "bad", `The heaviest second, on a sliding 1 s window: ${nf(peak)} Mbps at ${nf(analysis.peakAt)} s.`);
    $("stats-caption").hidden = false;
    const notes = evaluation.checks.filter((check) => (check.id === "peak" || check.id === "average") && check.state === "warn").map((check) => check.detail);
    $("stats-note").textContent = notes.join(" ");
    $("stats-note").hidden = notes.length === 0;
  }

  // I requisiti principali, uno per riga e in parole semplici: ok, oppure da sistemare con il valore che avrà dopo.
  // Per ogni riga: [etichetta, significato se va bene, se verrà sistemato, se resta da sistemare / è un avviso].
  const KEY_CHECKS = {
    codec: ["Video format", "The format TikTok keeps as it is", "Will be converted to H.264", "Needs H.264: export again in HandBrake"],
    size: ["Size", "Short side up to 1080 pixels", "Will be resized, nothing is cropped", "Too big: the short side must be 1080 or less"],
    fps: ["Smoothness", "Frames per second, like the untouched posts", "Will be converted to 60 frames per second", "The untouched posts we found were all 60"],
    cfr: ["Steady timing", "Every frame lasts the same", "Will be made perfectly steady", "Some frames are uneven: it still works"],
    peak: ["Heaviest second", "Plays smoothly even on average internet", "", "Viewers on slow internet may see pauses"],
    audio: ["Sound", "Standard sound format", "Will be converted to AAC", "Not AAC: it still works"],
  };

  function renderKeyChecks(evaluation, info, plan = null) {
    const targets = plan ? {
      codec: "H.264",
      size: `${plan.width}×${plan.height}`,
      fps: `${plan.fps || round(info.fps)} FPS`,
      cfr: "Steady",
      audio: "AAC",
    } : {};
    const rows = evaluation.checks.filter((check) => KEY_CHECKS[check.id]).map((check, index) => {
      const [label, ok, fix, warn] = KEY_CHECKS[check.id];
      const fixed = plan?.reencode && targets[check.id] && (check.state === "warn" || check.state === "bad");
      const kind = fixed ? "fix" : check.state === "bad" ? "warn" : check.state === "ok" ? "" : check.state;
      const li = el("li", kind);
      li.style.animationDelay = `${index * 45}ms`;
      li.title = check.detail;
      const badge = el("span", "kc-ic");
      badge.append(icon(fixed ? "arrow" : STATE_ICON[check.state === "bad" ? "warn" : check.state]));
      const text = el("span", "kc-label");
      const meaning = fixed ? fix : check.state === "ok" ? ok : check.id === "audio" && check.state === "info" ? "This video has no sound" : warn;
      text.append(document.createTextNode(label), el("small", "", meaning));
      const value = el("span", "kc-value");
      if (fixed) value.append(el("s", "", check.value), el("span", "kc-to", targets[check.id]));
      else value.textContent = check.id === "audio" && check.state !== "info" ? check.value.split(" · ")[0] : check.value;
      li.append(badge, text, value);
      return li;
    });
    $("key-checks").replaceChildren(...rows);
    $("key-checks").hidden = rows.length === 0;
  }

  function renderChart() {
    const analysis = current?.analysis;
    if (!analysis) return;
    $("chart").hidden = false;
    const svg = $("chart-svg");
    const wrap = $("chart-wrap");
    const tip = $("chart-tip");
    const width = Math.max(240, Math.round(wrap.clientWidth));
    const height = 120, top = 18, bottom = 1;
    const values = analysis.perSecond;
    const n = values.length;
    const max = Math.max(PEAK_OK * 1.3, ...values) * 1.1;
    const plot = height - top - bottom;
    const y = (v) => top + plot - v / max * plot;
    const step = width / n;
    const gap = step > 8 ? Math.min(3, step * 0.25) : step > 3 ? 1 : 0;
    const barWidth = Math.max(0.8, step - gap);
    svg.setAttribute("viewBox", `0 0 ${width} ${height}`);

    const defs = svgEl("defs");
    const gradient = (id, a, b) => {
      const g = svgEl("linearGradient", { id, x1: 0, y1: 0, x2: 0, y2: 1 });
      g.append(svgEl("stop", { offset: 0, "stop-color": a }), svgEl("stop", { offset: 1, "stop-color": b, "stop-opacity": 0.55 }));
      defs.append(g);
    };
    gradient("g-ok", "#38bdf8", "#6366f1");
    gradient("g-warn", "#fbbf24", "#f59e0b");
    gradient("g-bad", "#f87171", "#ef4444");

    const group = svgEl("g", { class: reduceMotion ? "" : "grow" });
    group.style.transformOrigin = `0 ${height - bottom}px`;
    const bars = values.map((value, i) => {
      const h = Math.max(1.5, value / max * plot);
      const kind = value <= PEAK_OK ? "ok" : value <= PEAK_HIGH ? "warn" : "bad";
      const bar = svgEl("rect", {
        x: (i * step + gap / 2).toFixed(2), y: (top + plot - h).toFixed(2),
        width: barWidth.toFixed(2), height: h.toFixed(2), rx: Math.min(3, barWidth / 2).toFixed(2),
        fill: `url(#g-${kind})`, class: "bar",
      });
      group.append(bar);
      return bar;
    });
    const limitY = y(PEAK_OK).toFixed(2);
    const base = svgEl("line", { x1: 0, x2: width, y1: height - bottom, y2: height - bottom, class: "grid" });
    const limit = svgEl("line", { x1: 0, x2: width, y1: limitY, y2: limitY, class: "limit" });
    const limitLabel = svgEl("text", { x: width - 2, y: Number(limitY) - 4, "text-anchor": "end", class: "limit-label" });
    limitLabel.textContent = `${PEAK_OK} Mbps`;
    let top1 = 0;
    for (let i = 1; i < n; i++) if (values[i] > values[top1]) top1 = i;
    const peakX = top1 * step + step / 2;
    const peakDot = svgEl("circle", { cx: peakX.toFixed(2), cy: (y(values[top1]) - 4).toFixed(2), r: 3.2, class: "peak-dot" });
    const cursor = svgEl("line", { x1: 0, x2: 0, y1: top - 6, y2: height - bottom, class: "cursor", visibility: "hidden" });
    const title = svgEl("title");
    title.textContent = `Bitrate per second: lowest ${nf(analysis.minMbps)}, average ${nf(analysis.averageMbps)}, peak ${nf(analysis.peakMbps)} Mbps.`;
    svg.replaceChildren(title, defs, base, group, limit, limitLabel, peakDot, cursor);

    let active = -1;
    const clear = () => {
      if (active >= 0) bars[active].classList.remove("active");
      active = -1;
      svg.classList.remove("hovering");
      cursor.setAttribute("visibility", "hidden");
      tip.hidden = true;
    };
    svg.onpointermove = (event) => {
      const box = svg.getBoundingClientRect();
      const i = Math.max(0, Math.min(n - 1, Math.floor((event.clientX - box.left) / box.width * n)));
      if (i === active) return;
      if (active >= 0) bars[active].classList.remove("active");
      active = i;
      bars[i].classList.add("active");
      svg.classList.add("hovering");
      const x = i * step + step / 2;
      cursor.setAttribute("x1", x.toFixed(2));
      cursor.setAttribute("x2", x.toFixed(2));
      cursor.setAttribute("visibility", "visible");
      const v = values[i];
      tip.replaceChildren(el("b", "", `${nf(v)} Mbps`), el("small", "", `${i}–${Math.min(i + 1, Math.ceil(current.info.seconds))} s · ${nf(v / 8)} MB/s`));
      tip.hidden = false;
      tip.style.left = `${Math.max(48, Math.min(box.width - 48, x / width * box.width))}px`;
    };
    svg.onpointerleave = clear;
    const seconds = current.info.seconds;
    $("chart-mid").textContent = `${Math.round(seconds / 2)} s`;
    $("chart-end").textContent = `${Math.round(seconds)} s`;
  }

  function renderCompression(result) {
    $("compression").hidden = false;
    $("details").hidden = false;
    $("comp-icon").className = `card-icon ${result.state}`;
    $("comp-title").textContent = result.title;
    $("comp-summary").textContent = result.summary;
    $("comp-rows").replaceChildren(...result.rows.map((row) => {
      const div = el("div", row.state);
      const dd = el("dd", "", row.value);
      dd.title = row.value;
      div.append(el("dt", "", row.label), dd);
      return div;
    }));
    $("comp-tips").replaceChildren(...result.tips.map((tip) => el("li", "", tip)));
  }

  function renderChecks(checks) {
    const shown = checks.filter((check) => check.id !== "average" && check.id !== "peak");
    $("checks").replaceChildren(...shown.map((check) => {
      const li = el("li", `${check.state}${check.state === "warn" || check.state === "bad" ? " wide" : ""}`);
      li.title = check.detail;
      const badge = el("span", "ic");
      badge.append(icon(STATE_ICON[check.state]));
      const text = el("span", "txt");
      text.append(el("span", "label", check.label), el("span", "value", check.value));
      if (li.classList.contains("wide")) text.append(el("span", "detail", check.detail));
      li.append(badge, text);
      return li;
    }));
    const scored = checks.filter((check) => check.state !== "info");
    const ok = scored.filter((check) => check.state === "ok").length;
    const pill = $("checks-score");
    pill.textContent = `${ok}/${scored.length} ok`;
    pill.className = `pill ${ok === scored.length ? "ok" : scored.some((check) => check.state === "bad") ? "bad" : "warn"}`;
    $("profile").hidden = false;
  }

  // ---------- Piano: cosa succede premendo il pulsante ----------

  // Stima prudente del tempo di x264 nel browser, dalle prove del 3/11/2026 (8 thread, 1440×1080: 15-20
  // fotogrammi al secondo). Su computer più lenti ci vuole di più: per questo è un intervallo.
  function estimate(info, plan) {
    const threads = Math.min(8, navigator.hardwareConcurrency || 4);
    const speed = 16 * (1555200 / (plan.width * plan.height)) * Math.pow(threads / 8, 0.8);
    const seconds = info.seconds * plan.rate / speed + 4;
    const low = seconds * 0.8, high = seconds * 1.7;
    if (high < 60) return `about ${Math.max(10, Math.round(high / 10) * 10)} s`;
    const min = (s) => Math.max(1, Math.round(s / 60));
    return min(low) === min(high) ? `about ${min(high)} min` : `about ${min(low)}–${min(high)} min`;
  }

  // mode: patch (solo la patch) | convert (x264 a qualità piena) | cap (x264 con il limite dei picchi)
  function renderPlan(mode, info, needs) {
    const plan = originalPlan(info, { force60: needs.fps, maxMbps: mode === "cap" ? peakChoice : null, encode: !!current.source?.encode });
    const name = outputName();
    const audio = current.source?.analysis?.audio;
    const items = [];
    const item = (title, text, chips = []) => items.push([title, text, chips]);
    if (mode !== "patch") {
      // Cosa cambia, in parole semplici; i dettagli tecnici restano nelle etichette piccole.
      const changes = [
        plan.fps && `${round(info.fps)} → 60 frames per second`,
        plan.resize && `${Math.round(info.width)}×${Math.round(info.height)} → ${plan.width}×${plan.height}`,
        info.codec && !/^avc/.test(info.codec) && `${String(info.codec).toUpperCase()} → H.264`,
      ].filter(Boolean);
      const chips = [["x264", "slow"], ["RF", "18"], [`${plan.fps || round(info.fps)} FPS`, "constant"],
        ...(audio ? [audio.codec === "aac" ? ["sound", "copied"] : ["AAC", "320 kbps"]] : [])];
      if (mode === "cap") {
        item("Make the heaviest seconds lighter", `Every second stays under ${peakChoice} Mbps. Only those seconds lose a little detail.`,
          [...chips, [`≤ ${peakChoice} Mbps`, ""]]);
      } else {
        item(changes.length ? "Convert your video" : "Compress your video", `${changes.length ? `${changes.join(", ")}. ` : ""}Same engine and settings as the HandBrake preset, at top quality.`, chips);
        item("Measure the heaviest second", "If it's above 25 Mbps, you choose: best quality, or smoother playback on slow internet.");
      }
    }
    item("Add the HQ Upload tweak", mode === "patch"
      ? "A tiny change in the file's header. Picture and sound stay exactly the same."
      : "A tiny change in the file's header, nothing else.");
    item(`Save “${name}”`, "In your Downloads folder, ready for TikTok.");
    $("plan-steps").replaceChildren(...items.map(([title, text, chips], index) => {
      const li = el("li");
      li.style.animationDelay = `${index * 60}ms`;
      const div = el("div");
      div.append(el("b", "", title), el("span", "", text));
      if (chips.length) {
        const box = el("span", "plan-chips");
        box.append(...chips.map(([label, value]) => {
          const chip = el("i");
          chip.append(el("b", "", label), document.createTextNode(value ? ` ${value}` : ""));
          return chip;
        }));
        div.append(box);
      }
      li.append(div);
      return li;
    }));
    $("plan-title").textContent = "What will happen";
    const time = $("plan-time");
    time.hidden = mode === "patch";
    if (mode !== "patch") time.replaceChildren(icon("clock"), document.createTextNode(estimate(info, plan)));
    $("plan").hidden = false;
    return plan;
  }

  function renderHandBrake(info, needs, open) {
    $("hb-alt").hidden = false;
    $("hb-alt").open = open;
    $("hb-alt-sub").textContent = open ? "Ready-made preset and the steps to follow" : "Same encoder and settings, much faster";
    $("hb-steps").replaceChildren(...handbrakeSteps(info, needs).map((step) => {
      const li = el("li");
      const div = el("div");
      div.append(el("b", "", step.title), el("span", "", step.text));
      li.append(div);
      return li;
    }));
    $("hb-preset-label").textContent = `Download the “${handbrakePreset(info).name}” preset`;
  }

  // ---------- Picchi: qualità piena o limite ----------

  const CAPS = [30, 25];

  // phase "before": file già pronto, un limite vuol dire ricodificarlo.
  // phase "after": file appena convertito senza limite, in attesa di essere scaricato.
  // Restituisce false se i picchi non sono alti e la scheda resta nascosta.
  function renderPeaks(analysis, phase) {
    const peak = analysis?.peakMbps ?? 0;
    const caps = CAPS.filter((cap) => cap < peak);
    peakChoice = null;
    if (peak <= PEAK_OK || !caps.length || !canCompress) {
      $("peaks").hidden = true;
      return false;
    }
    $("peaks-title").textContent = peak > PEAK_HIGH ? "Some seconds are very heavy" : "Some seconds are heavy";
    $("peaks-why").textContent = `At ${nf(analysis.peakAt)} s the video needs ${nf(peak)} Mbps (${nf(peak / 8)} MB/s). `
      + "On slow internet the video may pause there. Keep the best quality, or make those seconds lighter.";
    const choice = (value, title, sub) => {
      const button = el("button");
      button.type = "button";
      button.setAttribute("role", "radio");
      button.dataset.cap = String(value ?? "");
      button.append(el("b", "", title), el("small", "", sub));
      button.addEventListener("click", () => selectPeak(value, phase));
      return button;
    };
    $("peaks-choices").replaceChildren(
      choice(null, "Best quality", "Keep it as it is"),
      ...caps.map((cap, i) => choice(cap, `Max ${cap} Mbps`, i === caps.length - 1 && caps.length > 1 ? "Smoothest playback" : "Smoother playback")),
    );
    selectPeak(null, phase);
    $("peaks").hidden = false;
    $("stats-note").hidden = true; // la scheda Picchi dice già la stessa cosa
    return true;
  }

  function selectPeak(value, phase) {
    peakChoice = value;
    for (const button of $("peaks-choices").children) button.setAttribute("aria-checked", String(button.dataset.cap === String(value ?? "")));
    $("peaks-hint").textContent = !value
      ? (phase === "after" ? "You'll download the converted video as it is." : "Your video stays exactly as it is.")
      : `Every second stays under ${value} Mbps (${nf(value / 8)} MB/s): only the heaviest seconds lose a little detail. `
        + (phase === "after" ? "It converts again from your original, so it takes the same time again." : "This needs one more conversion of your video.");
    $("run-original-label").textContent = !value
      ? (phase === "after" ? "Download in best quality" : "Prepare for TikTok")
      : phase === "after" ? `Convert again, max ${value} Mbps` : `Make it lighter & prepare`;
    if (phase === "before" && current?.source) {
      const { info } = current.source;
      renderPlan(value ? "cap" : "patch", info, current.evaluation.needs);
      coach(value ? "Good choice for slow internet." : "Ready, with one choice to make.",
        value ? `Press **${$("run-original-label").textContent}**. Only the heaviest seconds lose a little detail.`
          : `Some seconds are heavy (${nf(current.analysis.peakMbps)} Mbps). Keep the best quality, or make them lighter for slow internet. Then press **Prepare for TikTok**.`, "warn");
    }
  }

  // "30 FPS and 1440p": la versione breve per il titolo; i dettagli sono nei controlli.
  function fixReasons(info, needs) {
    const fps = round(current.analysis?.medianFps || info.fps);
    const shortSide = Math.round(Math.min(info.width, info.height));
    const list = [needs.fps && `${fps} FPS`, needs.resize && `${shortSide}p`, needs.codec && info.codec.toUpperCase()].filter(Boolean);
    return list.length > 1 ? `${list.slice(0, -1).join(", ")} and ${list.at(-1)}` : list[0];
  }

  // Il preset HQ non si riconosce dal file (encoder diverso, oppure impostazioni non scritte):
  // si chiede come è stato fatto. Un file molto pesante o non H.264/HEVC ha l'aria di un master.
  function askOrigin() {
    const { info, analysis } = current;
    for (const id of ["verdict", "stats", "stats-caption", "stats-note", "details"]) $(id).hidden = true;
    const looksMaster = (analysis?.averageMbps || 0) > 35 || !/^(avc|hvc|hev)/.test(info.codec || "");
    $("origin-guess").hidden = !looksMaster;
    $("origin").querySelector('[data-origin="master"]').classList.toggle("suggested", looksMaster);
    $("origin").hidden = false;
    setDock("none");
    coach("How was this video made?",
      `I couldn't find the HQ Upload preset in this file${looksMaster ? ", and it's very heavy: it looks like an original export" : ""}. Pick the right answer: it decides how I prepare it.`);
  }

  // Dopo aver capito com'è stato fatto il video: cosa serve e quale pulsante premere.
  function decide() {
    const { info, analysis, evaluation } = current;
    const { needs, verdict } = evaluation;
    const master = origin === "master";
    current.source.encode = master;
    $("origin").hidden = true;
    for (const id of ["verdict", "stats", "details"]) $(id).hidden = false;
    $("stats-caption").hidden = !analysis;
    const reasons = fixReasons(info, needs);
    if (verdict === "fix" || master) {
      if (canCompress) {
        const plan = renderPlan("convert", info, needs);
        renderKeyChecks(evaluation, info, plan);
        renderHandBrake(info, needs, false);
        const label = needs.fps ? "Convert to 60 FPS & prepare" : verdict === "fix" ? "Convert & prepare" : "Compress & prepare";
        const time = estimate(info, plan);
        $("run-original-label").textContent = label;
        setDock("cta");
        if (master) {
          setVerdict("needs-fix", "Original export", reasons ? `It's ${reasons}` : "Ready to compress",
            "HQ Upload compresses it with the same settings as the HandBrake preset.", evaluation.checks);
          coach("Great: the original is the best starting point.",
            `Press **${label}**. I'll compress it once with the HQ settings${reasons ? ` and fix the ${needs.fps ? "frame rate" : "size"}` : ""}: it takes ${time}, on your computer.`);
        } else if (origin === "other") {
          setVerdict("needs-fix", "One thing to fix", `It's ${reasons}`, "HQ Upload can fix it for you, below.", evaluation.checks);
          coach("This video needs one conversion.", `It's ${reasons}. Press **${label}** (${time}). It was already compressed once, so starting from the master would look better.`, "warn");
        } else {
          setVerdict("needs-fix", "One thing to fix", `It's ${reasons}`, "HQ Upload can fix it for you, below.", evaluation.checks);
          coach("Your HandBrake export still needs one fix.", `It's ${reasons}: was the HQ preset selected? Press **${label}** to fix it here (${time}), or export the master again with the preset.`, "warn");
        }
      } else {
        renderKeyChecks(evaluation, info);
        renderHandBrake(info, needs, true);
        $("plan-title").textContent = "Fix it in HandBrake";
        $("plan-steps").replaceChildren();
        $("plan-time").hidden = true;
        $("plan").hidden = false;
        setVerdict("needs-fix", "One thing to fix", reasons ? `It's ${reasons}` : "Needs compressing", "This browser can't convert videos: HandBrake can.", evaluation.checks);
        setDock("none");
        coach("This video needs converting.", "This browser can't run the converter. Follow the **HandBrake** steps below, then drop the new video here.", "warn");
      }
      return;
    }
    renderKeyChecks(evaluation, info);
    setVerdict(verdict === "ready" ? "ready" : "warn",
      origin === "detected" ? "HQ preset detected" : verdict === "ready" ? "All good" : "Good, with tips",
      "Ready for TikTok",
      verdict === "ready" ? "Everything matches the posts TikTok keeps untouched." : "The yellow tips are optional: nothing blocks you.",
      evaluation.checks);
    $("run-original-label").textContent = "Prepare for TikTok";
    setDock("cta");
    renderPlan("patch", info, needs);
    const peaks = renderPeaks(analysis, "before");
    const intro = origin === "detected" ? "I recognised the HandBrake HQ preset. "
      : origin === "other" ? "It was already compressed once: it works, but starting from the master would look better. " : "";
    if (peaks) {
      coach("Ready, with one choice to make.", `${intro}Some seconds are heavy (${nf(analysis.peakMbps)} Mbps). Keep the best quality, or make them lighter for slow internet. Then press **Prepare for TikTok**.`, "warn");
    } else if (verdict === "ready") {
      coach("All good: your video is ready!", `${intro}Press **Prepare for TikTok**. I only add a tiny tweak to the file's header: picture and sound stay exactly the same.`, origin === "other" ? "warn" : "ok");
    } else {
      coach("Your video is ready.", `${intro}The yellow tips are optional and don't block anything. Press **Prepare for TikTok**.`, "ok");
    }
  }

  // givenOrigin: come è stato fatto il video, se già noto (scheda di conversione, "usa comunque").
  async function select(file, givenOrigin = null) {
    if (busy) return;
    // Dopo "l'ho compresso in altro modo" il file successivo è il master richiesto.
    const expectingMaster = !!retryFile && !givenOrigin;
    retryFile = null;
    reset();
    origin = givenOrigin;
    const selectedId = selectionId;
    if (!file) return;
    showFile(file);
    coach("Checking your video…", "Looking at its format, size, smoothness and how heavy each second is. It takes a moment.", "work");
    setVerdict("busy", "Checking", "Reading your file…", "Nothing is uploaded: it all happens here");
    setDock("cta");
    $("run-original-label").textContent = "Checking…";
    try {
      const info = HQPatcher.inspect(await file.arrayBuffer());
      if (selectedId !== selectionId) return;
      $("file-meta").textContent = `${Math.round(info.width)}×${Math.round(info.height)} · ${round(info.fps)} FPS · ${formatMB(file.size)} MB`;
      $("thumb-dur").textContent = clock(info.seconds);
      if (info.alreadyPatched) {
        $("stats").hidden = true;
        setVerdict("bad", "Already prepared", "This file was already prepared",
          "It's an _original.mp4 made by HQ Upload: you can upload it as it is.");
        coach("This video is already prepared.", "You can upload it to TikTok as it is. To prepare another video, drop the original export instead. To check a post you've published, open **Verify**.", "warn");
        setDock("none");
        return;
      }
      current = { file, info, analysis: null, evaluation: null, encoder: null };
      setVerdict("busy", "Checking", "Measuring every second…", "Size and timing of each frame");
      const [analysis, encoder] = await Promise.all([
        analyzeVideo(file, info).catch(() => null),
        detectEncoder(file).catch(() => null),
      ]);
      if (selectedId !== selectionId) return;
      const evaluation = evaluate(info, analysis, encoder);
      Object.assign(current, { analysis, evaluation, encoder, source: { file, info, analysis, force60: evaluation.needs.fps } });

      const chips = [];
      if (encoder?.app) chips.push(el("span", /HandBrake/.test(encoder.app) ? "hb" : "", encoder.app.replace(/ \d.*$/, "")));
      if (encoder?.encoder === "x264" && encoder.options?.rc === "crf") chips.push(el("span", "", `RF ${Number(encoder.options.crf)}`));
      if (analysis?.audio) chips.push(el("span", "", analysis.audio.codec.toUpperCase()));
      $("file-chips").replaceChildren(...chips);

      renderStats(analysis, evaluation);
      renderChart();
      const compression = assessCompression(encoder, info, analysis);
      renderCompression(compression);
      renderChecks(evaluation.checks);

      // Il preset HQ si riconosce dalle impostazioni che x264 scrive nel file (RF 18, preset slow o migliore).
      if (!origin && compression.matchesPreset) origin = "detected";
      if (!origin && expectingMaster) origin = "master";
      if (!origin) askOrigin();
      else decide();
      if (!analysis) say("The detailed analysis isn't available for this file: the checks use its header only.");
      updateControls();
    } catch (e) {
      if (selectedId !== selectionId) return;
      $("stats").hidden = true;
      setVerdict("bad", "Error", "Can't read this file", e.message);
      coach("I can't read this file.", "Make sure it's a video (MP4 or MOV) exported from your editor, then drop it again.", "bad");
      setDock("none");
    }
  }

  // ---------- Conversione in corso ----------

  const WORK_STEPS = [
    ["encode", "Converting your video"],
    ["patch", "Adding the HQ Upload tweak"],
    ["peaks", "Measuring the heaviest second"],
    ["save", "Saving to Downloads"],
  ];

  function showWorking(on, title = "Converting your video") {
    for (const id of ["verdict", "stats", "stats-caption", "plan", "peaks", "details"]) {
      if (on) $(id).hidden = true;
    }
    if (on) $("stats-note").hidden = true;
    $("working").hidden = !on;
    if (!on) return;
    $("work-steps").replaceChildren(...WORK_STEPS.map(([name, label]) => {
      const li = el("li");
      li.dataset.step = name;
      const badge = el("span", "ws-ic");
      li.append(badge, el("b", "", name === "encode" ? title : label), el("small"));
      return li;
    }));
    setWorkStep("encode");
    setWorkProgress(0, null);
  }

  function setWorkStep(name, detail = "") {
    const order = WORK_STEPS.map(([step]) => step);
    const index = order.indexOf(name);
    for (const li of $("work-steps").children) {
      const i = order.indexOf(li.dataset.step);
      li.className = i < index ? "done" : i === index ? "now" : "";
      li.querySelector(".ws-ic").replaceChildren(...(i < index ? [icon("check")] : []));
      if (i === index) li.querySelector("small").textContent = detail;
      else if (i < index) li.querySelector("small").textContent = "";
    }
  }

  function setWorkProgress(value, eta, speed = 0) {
    const c = 2 * Math.PI * 52;
    $("work-arc").style.strokeDasharray = `${(c * Math.max(0, Math.min(1, value))).toFixed(1)} 400`;
    $("work-pct").textContent = `${Math.round(value * 100)}%`;
    $("work-eta").textContent = eta == null ? "starting…" : value >= 1 ? "finishing…" : `${timeLeft(eta)} left`;
    // Finché x264 non ha prodotto il primo fotogramma l'anello gira invece di restare fermo a 0.
    document.querySelector(".work-ring").classList.toggle("idle", value < 0.005);
    if (speed) {
      const now = [...$("work-steps").children].find((li) => li.classList.contains("now"));
      if (now?.dataset.step === "encode") now.querySelector("small").textContent = `${nf(speed, 0)} fps`;
    }
  }

  // ---------- Scheda per la ricodifica, download (tramite il guscio) ----------

  // Il guscio conserva il File in IndexedDB e apre la scheda; il popup si chiude.
  const openTab = (job = null) => hq.call("openTab", [job]);

  function downloadBlob(blob, name) {
    hq.call("download", [blob, name]);
    return name;
  }

  // ---------- Preparazione ----------

  function burst() {
    if (reduceMotion) return;
    const box = document.querySelector("#done .burst");
    const colors = ["#38bdf8", "#3b82f6", "#6366f1", "#34d399", "#bae6fd", "#ffffff"];
    box.replaceChildren(...Array.from({ length: 26 }, (_, i) => {
      const piece = el("i");
      const angle = (i / 26) * Math.PI * 2 + Math.random() * 0.4;
      const distance = 60 + Math.random() * 90;
      piece.style.setProperty("--x", `${Math.cos(angle) * distance}px`);
      piece.style.setProperty("--y", `${Math.sin(angle) * distance * 0.7 + 30}px`);
      piece.style.setProperty("--r", `${Math.random() * 540 - 270}deg`);
      piece.style.background = colors[i % colors.length];
      piece.style.animationDelay = `${Math.random() * 120}ms`;
      return piece;
    }));
  }

  // Dopo una ricodifica i numeri del file di partenza non valgono più:
  // il rapporto passa a descrivere il file convertito.
  async function describeOutput(output, name, maxMbps) {
    const file = new File([output], name, { type: "video/mp4" });
    const info = HQPatcher.inspect(output);
    const analysis = await analyzeVideo(file, info).catch(() => null);
    const encoder = await detectEncoder(file).catch(() => null);
    const evaluation = evaluate(info, analysis, encoder);
    Object.assign(current, { info, analysis, evaluation, encoder });
    $("file-meta").textContent = `${Math.round(info.width)}×${Math.round(info.height)} · ${round(info.fps)} FPS · ${formatMB(output.byteLength)} MB · converted`;
    $("file-chips").replaceChildren(el("span", "hb", "Converted by HQ Upload"),
      el("span", "", maxMbps ? `Max ${maxMbps} Mbps` : "Best quality"));
    renderStats(analysis, evaluation);
    if (analysis) renderChart(); else $("chart").hidden = true;
    renderCompression(assessCompression(encoder, info, analysis));
    renderChecks(evaluation.checks);
    renderKeyChecks(evaluation, info);
  }

  const outputName = () => current.source.file.name.replace(/\.[^.]+$/, "") + "_original.mp4";

  // Il rapporto del file convertito è già stato mostrato da run(): qui solo MD5, download e storico.
  async function finish(output, summary) {
    $("peaks").hidden = true;
    if (!$("working").hidden) setWorkStep("save", "fingerprint");
    setWorking(true, "Saving your video…", 0);
    const md5 = await HQMd5.hash(output, (value) => setWorking(true, `Saving your video · ${Math.round(value * 100)}%`, value));
    const name = downloadBlob(new Blob([output], { type: "video/mp4" }), outputName());
    const check = HQPatcher.inspect(output);
    const entry = {
      md5, name, bytes: output.byteLength, at: Date.now(),
      width: Math.round(check.width), height: Math.round(check.height), fps: round(check.fps),
      transcoded: summary.transcoded,
    };
    const stored = (await storage.get(PREPARED_KEY))[PREPARED_KEY] || [];
    await storage.set({ [PREPARED_KEY]: [entry, ...stored.filter((item) => item.md5 !== md5)].slice(0, 30) });
    setWorking(false);
    showWorking(false);
    for (const id of ["plan", "verdict", "stats", "stats-note", "stats-caption"]) $(id).hidden = true;
    $("details").hidden = false;
    say("");
    $("done-title").textContent = summary.title;
    $("done-file").textContent = `${name} · ${summary.detail}`;
    $("done-size").textContent = `${formatMB(output.byteLength)} MB`;
    $("done-video").textContent = `${entry.width}×${entry.height} · ${entry.fps} FPS`;
    $("done-md5").textContent = md5;
    $("upload-name").textContent = name;
    $("done").hidden = false;
    goStep("upload");
    coach("Done! Your video is in your Downloads folder.", `It's called **${name}**. Now post it on TikTok: follow the 5 steps below.`, "ok");
    burst();
    window.scrollTo({ top: 0, behavior: reduceMotion ? "auto" : "smooth" });
  }

  const timeLeft = (eta) => eta < 60 ? `${Math.max(5, Math.round(eta / 5) * 5)} s` : `${Math.round(eta / 60)} min`;

  // Converte (o applica solo la patch) partendo sempre dal file scelto, anche dopo una prima conversione.
  async function run({ force60 = false, maxMbps = null } = {}) {
    if (!current || busy) return;
    const { file, info, analysis } = current.source;
    const encode = !!current.source.encode;
    const plan = originalPlan(info, { force60, maxMbps, encode });
    pending = null;
    busy = true;
    updateControls();
    if (!inTab && plan.reencode) {
      say("Opening a tab for the conversion…");
      try {
        await openTab({ file, mode: "original", force60, maxMbps, origin });
      } catch (e) {
        say("Error: " + e.message, "bad");
      } finally {
        busy = false;
        updateControls();
      }
      return;
    }
    if (plan.reencode) {
      showWorking(true, maxMbps ? `Making it lighter (max ${maxMbps} Mbps)` : "Converting your video");
      coach("Converting your video…", `This takes ${estimate(info, plan)}. Keep this tab open: everything happens on your computer, nothing is uploaded.`, "work");
      window.scrollTo({ top: 0, behavior: reduceMotion ? "auto" : "smooth" });
    }
    say("");
    setWorking(true, plan.reencode ? "Starting…" : "Adding the tweak…", 0);
    await nextFrame();
    try {
      let encoded = false;
      const result = await prepareOriginalVideo(file, info, {
        force60, maxMbps, encode, audioCodec: analysis?.audio?.codec || null,
      }, ({ value, speed, eta }) => {
        const left = eta == null || value < 0.02 ? "" : ` · ${timeLeft(eta)} left`;
        setWorking(true, value > 0 ? `Converting · ${Math.round(value * 100)}%${left}` : "Starting…", value);
        setWorkProgress(value, value < 0.02 ? null : eta, speed);
        if (value >= 1 && !encoded) {
          encoded = true;
          setWorkStep("patch");
        }
      });
      if (result.transcoded) {
        setWorkStep("peaks");
        setWorkProgress(1, 0);
        setWorking(true, "Measuring the heaviest second…", 1);
        await describeOutput(result.output, outputName(), maxMbps);
      }
      const summary = result.transcoded ? {
        transcoded: true, title: "Converted and ready to post",
        detail: `${result.plan.width}×${result.plan.height} · ${result.plan.fps || round(info.fps)} FPS${maxMbps ? ` · max ${maxMbps} Mbps` : ""}`,
      } : {
        transcoded: false, title: "Ready to post",
        detail: "picture and sound untouched",
      };
      // Convertito a qualità piena con picchi alti: prima di scaricare decide l'utente.
      if (result.transcoded && !maxMbps && renderPeaks(current.analysis, "after")) {
        pending = { output: result.output, summary };
        setWorking(false);
        showWorking(false);
        for (const id of ["verdict", "stats", "stats-caption", "details"]) $(id).hidden = false;
        setVerdict("warn", "Converted", "One last choice",
          "Choose below, then press the button.", current.evaluation?.checks);
        setDock("cta");
        say("");
        coach("Converted! One last choice.", `Some seconds are heavy (${nf(current.analysis.peakMbps)} Mbps). Keep the **best quality**, or make them lighter for slow internet (it converts again).`, "warn");
        $("peaks").scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth", block: "center" });
        return;
      }
      await finish(result.output, summary);
    } catch (e) {
      setWorking(false);
      showWorking(false);
      for (const id of ["verdict", "stats", "stats-caption", "plan", "details"]) $(id).hidden = false;
      $("run-original-label").textContent = "Try again";
      say("Error: " + e.message, "bad");
      coach("Something went wrong.", e.message, "bad");
    } finally {
      busy = false;
      updateControls();
    }
  }

  // ---------- Verifica dei post ----------

  function parseLink(text) {
    const value = text.trim();
    if (/^[1-9]\d{14,24}$/.test(value)) return { id: value };
    let url;
    try { url = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`); } catch { return null; }
    if (!/(^|\.)tiktok\.com$/i.test(url.hostname)) return null;
    const match = url.pathname.match(/\/(?:video|photo|player\/v1|embed\/v2|embed)\/(\d{15,25})/);
    if (match) return { id: match[1] };
    if (/^(vm|vt)\./i.test(url.hostname) || url.pathname.startsWith("/t/")) return { short: `${url.origin}${url.pathname}` };
    return null;
  }

  const playerUrl = (id) => `https://www.tiktok.com/player/v1/${id}?controls=1&autoplay=1&muted=1&hqup_verify=1`;

  async function openVerification(target) {
    await chrome.tabs.create({ url: target.id ? playerUrl(target.id) : `${target.short}#hqup-verify` });
    window.close();
  }

  const VERDICTS = {
    perfect: ["Original", "check"],
    partial: ["Extra versions", "alert"],
    recompressed: ["Re-compressed", "cross"],
    different: ["Different file", "alert"],
    unknown: ["Check again", "question"],
  };

  function relative(at) {
    const minutes = Math.round((Date.now() - at) / 60000);
    if (minutes < 1) return "just now";
    if (minutes < 60) return `${minutes} min ago`;
    const hours = Math.round(minutes / 60);
    if (hours < 24) return `${hours} h ago`;
    return new Date(at).toLocaleDateString("en-US", { day: "numeric", month: "short" });
  }

  function listItem({ kind, iconName, title, sub, tags, action }, index) {
    const li = el("li", kind);
    li.style.animationDelay = `${Math.min(index, 8) * 40}ms`;
    const badge = el("span", "ic");
    badge.append(icon(iconName));
    const body = el("span", "body");
    const t = el("span", "title", title);
    t.title = title;
    body.append(t, el("span", "sub", sub));
    if (tags.length) {
      const box = el("span", "tags");
      box.append(...tags.map(([text, accent]) => el("span", accent ? "accent" : "", text)));
      body.append(box);
    }
    li.append(badge, body);
    if (action) {
      const button = el("button", "icon-btn small");
      button.type = "button";
      button.title = action.label;
      button.setAttribute("aria-label", action.label);
      button.append(icon("refresh"));
      button.addEventListener("click", action.run);
      li.append(button);
    } else {
      li.append(el("span"));
    }
    return li;
  }

  async function renderHistory() {
    const data = await storage.get([PREPARED_KEY, CHECKS_KEY]);
    const checks = data[CHECKS_KEY] || {};
    const prepared = data[PREPARED_KEY] || [];
    const posts = Object.entries(checks).map(([id, list]) => ({ id, list, last: list[0] }))
      .filter((post) => post.last).sort((a, b) => b.last.at - a.last.at);
    $("history").replaceChildren(...posts.map(({ id, list, last }, index) => {
      const [label, iconName] = VERDICTS[last.verdict] || ["?", "question"];
      const tags = [[label, true]];
      tags.push([!last.recompressed ? "Original only" : last.recompressed === 1 ? "1 re-compressed copy" : `${last.recompressed} re-compressed copies`, false]);
      if (last.played?.role === "original") tags.push(["Plays the original", false]);
      else if (last.played?.role === "profile") tags.push(["Plays a copy", false]);
      if (last.identical) tags.push(["Identical bytes", false]);
      return listItem({
        kind: last.verdict, iconName,
        title: last.preparedName || `Post …${id.slice(-8)}`,
        sub: `${relative(last.at)}${list.length > 1 ? ` · ${list.length} checks` : ""} · ${id}`,
        tags, action: { label: "Check again", run: () => openVerification({ id }) },
      }, index);
    }));
    $("history-empty").hidden = posts.length > 0;
    const bySign = new Map(posts.map((post) => [post.last.sign, post]));
    $("prepared").replaceChildren(...prepared.map((file, index) => {
      const post = bySign.get(file.md5);
      const tags = post ? [[`Posted · ${(VERDICTS[post.last.verdict] || ["?"])[0]}`, true]] : [["Not verified", false]];
      tags.push([`MD5 ${file.md5.slice(0, 8)}`, false]);
      if (file.transcoded) tags.push(["Converted in HQ Upload", false]);
      return listItem({
        kind: post ? post.last.verdict : "file", iconName: "film", title: file.name,
        sub: `${relative(file.at)} · ${formatMB(file.bytes)} MB · ${file.width}×${file.height} · ${file.fps} FPS`,
        tags, action: post ? { label: "Check again", run: () => openVerification({ id: post.id }) } : null,
      }, index);
    }));
    $("prepared-empty").hidden = prepared.length > 0;
    const good = posts.filter((post) => post.last.verdict === "perfect").length;
    const attention = posts.length - good;
    $("verify-stats").hidden = posts.length === 0;
    $("vs-total").textContent = String(posts.length);
    $("vs-ok").textContent = String(good);
    $("vs-attn").textContent = String(attention);
    $("verify-count").hidden = attention === 0;
    $("verify-count").textContent = String(attention);
  }

  function showTab(name) {
    $("tabs").dataset.tab = name;
    for (const tab of ["prepare", "verify"]) {
      const active = tab === name;
      $(`tab-${tab}`).setAttribute("aria-selected", String(active));
      $(`panel-${tab}`).hidden = !active;
    }
    if (name === "verify") {
      renderHistory();
      paintStepper("verify");
      $("action").hidden = true;
      showCoach(["Last step: check your post.", "On TikTok, open your post, copy its link (Share → Copy link) and paste it below. I'll tell you if viewers get your original file."]);
    } else {
      paintStepper(guideStep);
      setDock(dockMode);
      if (guideCoach) showCoach(guideCoach);
      if (current?.analysis && $("details").open) requestAnimationFrame(renderChart);
    }
  }

  // ---------- Aggiornamenti ----------

  // L'app si aggiorna da sola (il guscio scarica e verifica i bundle firmati). Qui solo gli avvisi:
  // un aggiornamento appena scaricato (pulsante Restart) o un guscio troppo vecchio (va reinstallato).
  function banner(title, sub, action = null) {
    $("update-title").textContent = title;
    $("update-sub").textContent = sub;
    const link = $("update-link");
    link.hidden = !action;
    if (action?.href) {
      link.href = action.href;
      link.onclick = null;
    } else if (action) {
      link.removeAttribute("href");
      link.onclick = (event) => { event.preventDefault(); action.run(); };
    }
    if (action) link.textContent = action.label;
    $("update-banner").hidden = false;
  }

  function showNotices() {
    $("app-version").textContent = String(context.appVersion || "").split(".").slice(0, 2).join(".");
    $("app-version").title = `App ${context.appVersion} · extension ${context.shellVersion}`;
    const notice = context.notice;
    if (notice) banner(notice.title, notice.sub, notice.link ? { label: "Open", href: notice.link } : null);
    hq.on("updateReady", ({ version }) => {
      banner(`Version ${version} is ready`, busy ? "It starts next time you open HQ Upload." : "Restart HQ Upload to use it now.",
        busy ? null : { label: "Restart", run: () => { if (!busy) hq.call("reload"); } });
    });
  }

  // ---------- Impostazioni ----------

  function setPatchNote() {
    $("toggle-note").textContent = toggle.checked
      ? "On TikTok, removes the web editor's data and shows a panel with the result."
      : "Off: the request is sent as it is. Reload TikTok after changing this.";
    $("patch-off").hidden = toggle.checked;
  }

  function openSettings(open) {
    $("settings").hidden = !open;
    if (open) toggle.focus();
  }

  // ---------- Eventi ----------

  $("tab-prepare").addEventListener("click", () => showTab("prepare"));
  $("tab-verify").addEventListener("click", () => showTab("verify"));
  for (const button of document.querySelectorAll("#stepper [data-go]")) {
    button.addEventListener("click", () => {
      if (busy) return;
      showTab("prepare");
      retryFile = null;
      reset();
    });
  }
  for (const button of document.querySelectorAll("[data-origin]")) {
    button.addEventListener("click", () => {
      if (busy || !current) return;
      if (button.dataset.origin === "other") {
        // Comprimere due volte toglie qualità: si chiede il master, ma questo file resta a disposizione.
        retryFile = current.source.file;
        reset();
        return;
      }
      origin = button.dataset.origin;
      decide();
      updateControls();
    });
  }
  $("use-anyway").addEventListener("click", () => {
    if (retryFile && !busy) select(retryFile, "other");
  });
  for (const button of document.querySelectorAll("[data-preset]")) {
    button.addEventListener("click", () => {
      const [width, height] = button.dataset.preset.split("x").map(Number);
      const preset = handbrakePreset({ width, height });
      downloadBlob(new Blob([preset.json], { type: "application/json" }), preset.fileName);
      button.classList.add("saved");
      coach("Preset saved to your Downloads.", `In HandBrake: Presets → Import → **${preset.fileName}**. Encode your master with it, then drop the HandBrake export here: I'll recognise the preset by itself.`, "ok");
    });
  }
  fileInput.addEventListener("change", () => select(fileInput.files[0]));
  drop.addEventListener("dragover", (event) => {
    event.preventDefault();
    if (!busy) drop.classList.add("drag");
  });
  ["dragleave", "drop"].forEach((type) => drop.addEventListener(type, () => drop.classList.remove("drag")));
  // Si può trascinare un video in qualunque momento della guida.
  document.addEventListener("dragover", (event) => event.preventDefault());
  document.addEventListener("drop", (event) => {
    event.preventDefault();
    const file = event.dataTransfer?.files?.[0];
    if (!file || busy) return;
    showTab("prepare");
    select(file);
  });
  $("file-clear").addEventListener("click", () => { if (!busy) reset(); });
  $("done-again").addEventListener("click", () => { if (!busy) reset(); });
  cta.addEventListener("click", async () => {
    if (!current) return;
    if (!pending || peakChoice) {
      run({ force60: !!current.source?.force60, maxMbps: peakChoice });
      return;
    }
    const { output, summary } = pending;
    pending = null;
    busy = true;
    updateControls();
    try {
      await finish(output, summary);
    } finally {
      busy = false;
      updateControls();
    }
  });
  $("hb-preset").addEventListener("click", () => {
    if (!current) return;
    const preset = handbrakePreset(current.source?.info || current.info);
    downloadBlob(new Blob([preset.json], { type: "application/json" }), preset.fileName);
    say(`Preset saved to Downloads: in HandBrake use Presets → Import and pick “${preset.fileName}”.`, "ok");
  });
  $("details").addEventListener("toggle", () => {
    if ($("details").open && current?.analysis) requestAnimationFrame(renderChart);
  });
  $("done-md5-btn").addEventListener("click", async () => {
    const button = $("done-md5-btn");
    try {
      await hq.call("clipboard", [$("done-md5").textContent]);
      button.classList.add("copied");
      setTimeout(() => button.classList.remove("copied"), 1800);
    } catch {
      getSelection().selectAllChildren($("done-md5"));
    }
  });
  $("open-studio").addEventListener("click", () => {
    chrome.tabs.create({ url: "https://www.tiktok.com/tiktokstudio/upload" });
  });
  $("posted").addEventListener("click", () => {
    showTab("verify");
    $("verify-link").focus();
  });
  $("open-tab").addEventListener("click", () => {
    openTab().catch((e) => say("Error: " + e.message, "bad"));
  });
  $("open-settings").addEventListener("click", () => openSettings(true));
  $("patch-off").addEventListener("click", () => openSettings(true));
  for (const node of document.querySelectorAll("[data-close]")) node.addEventListener("click", () => openSettings(false));
  const openHelp = (open) => {
    $("help").hidden = !open;
    if (open) $("help").querySelector("[data-close-help].icon-btn").focus();
  };
  $("open-help").addEventListener("click", () => openHelp(true));
  for (const node of document.querySelectorAll("[data-close-help]")) node.addEventListener("click", () => openHelp(false));
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!$("settings").hidden) openSettings(false);
    if (!$("help").hidden) openHelp(false);
  });

  const verifyLink = $("verify-link");
  $("verify-form").addEventListener("submit", (event) => {
    event.preventDefault();
    const target = parseLink(verifyLink.value);
    const msg = $("verify-msg");
    if (!target) {
      msg.textContent = "Link not recognised. Paste the post's address (…tiktok.com/@name/video/number) or just the number.";
      msg.className = "hint bad";
      return;
    }
    msg.textContent = "Opening TikTok's player…";
    msg.className = "hint";
    openVerification(target).catch((e) => { msg.textContent = "Error: " + e.message; msg.className = "hint bad"; });
  });
  verifyLink.addEventListener("paste", () => setTimeout(() => {
    if (parseLink(verifyLink.value)) $("verify-form").requestSubmit();
  }, 0));
  verifyLink.addEventListener("input", () => { $("verify-msg").className = "hint"; });

  verifyBytes.addEventListener("change", () => storage.set({ verifyBytes: verifyBytes.checked }));
  toggle.addEventListener("change", () => {
    storage.set({ requestPatch: toggle.checked });
    setPatchNote();
  });
  chrome.storage.onChanged?.addListener?.((changes, area) => {
    if (area === "local" && (changes[CHECKS_KEY] || changes[PREPARED_KEY])) renderHistory();
  });
  let resizeTimer = 0;
  window.addEventListener("resize", () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => { if (current?.analysis && !$("chart").hidden && $("details").open) renderChart(); }, 120);
  });

  const settingsReady = storage.get(["requestPatch", "verifyBytes"]).then((r) => {
    toggle.checked = r.requestPatch !== false;
    verifyBytes.checked = r.verifyBytes !== false;
    setPatchNote();
  });
  renderHistory();
  dropGuide();
  showNotices();

  if (params.has("job")) {
    (async () => {
      await settingsReady;
      const job = await hq.call("takeJob", [params.get("job")]);
      if (!job || !job.file) throw new Error("The video isn't available any more. Pick it again in this tab.");
      await select(job.file, job.origin || "preset");
      if (current) await run({ force60: job.force60 === true, maxMbps: Number(job.maxMbps) || null });
    })().catch((e) => {
      goStep("check");
      say("Error: " + e.message, "bad");
      coach("Something went wrong.", e.message, "bad");
    });
  }
  updateControls();
})();

files.original.js:
// Modalità Originale: il profilo osservato sui post pubblici che TikTok non ricodifica
// (durata mvhd sconosciuta, H.264, lato corto fino a 1080 px, di solito 60 FPS).
// Se il file è già conforme applica solo la patch e il flusso audio/video resta identico;
// altrimenti esegue una sola ricodifica con x264 e le impostazioni del preset HandBrake, poi la stessa patch.
import { encodeLikeHandBrake } from "./x264.js";

const MAX_SHORT_SIDE = 1080;
const H264 = new Set(["avc1", "avc3"]);
const even = (value) => Math.max(2, Math.round(value / 2) * 2);
const round = (value) => Math.round(value * 100) / 100;

// maxMbps: limite dei picchi scelto dall'utente (25, 30…). Anche su un file già pronto obbliga a ricodificare.
// encode: il file è il master (export originale): va sempre compresso una volta con le impostazioni HQ.
export function originalPlan(info, { force60 = false, maxMbps = null, encode = false } = {}) {
  const shortSide = Math.min(info.width, info.height);
  const scale = shortSide > MAX_SHORT_SIDE ? MAX_SHORT_SIDE / shortSide : 1;
  // H.264 4:2:0 vuole lati pari: un export dispari viene portato al pari più vicino.
  const odd = Math.round(info.width) % 2 !== 0 || Math.round(info.height) % 2 !== 0;
  const reasons = [];
  if (!H264.has(info.codec)) reasons.push(`codec ${info.codec} → H.264`);
  if (scale < 1) reasons.push(`short side ${Math.round(shortSide)} → ${MAX_SHORT_SIDE}`);
  const fps = force60 && info.fps < 50 ? 60 : null;
  if (fps) reasons.push(`${round(info.fps)} → 60 FPS`);
  if (maxMbps) reasons.push(`peaks capped at ${maxMbps} Mbps`);
  if (encode && !reasons.length) reasons.push("compressed with the HQ settings");
  const resize = scale < 1 || (odd && reasons.length > 0);
  return {
    reencode: reasons.length > 0,
    reasons,
    resize,
    width: resize ? even(info.width * scale) : info.width,
    height: resize ? even(info.height * scale) : info.height,
    fps,
    rate: fps || info.fps,
    maxMbps: maxMbps || null,
  };
}

// Soglie di fluidità per chi guarda: il file arriva allo spettatore così com'è.
// Il tuo post del 1/11 non ricodificato aveva picchi di 42 Mbps: i picchi non
// risultano decidere la ricodifica, ma pesano sulle connessioni lente.
export const PEAK_OK = 25;
export const PEAK_HIGH = 45;
const fixed = (value, digits = 1) => value.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });

// Confronto con le caratteristiche comuni ai post osservati senza varianti.
// Sono osservazioni (14 casi al 1/11/2026), non regole documentate da TikTok.
// state: ok | warn | bad (da sistemare prima della patch) | info.
// encoder (facoltativo, da detectEncoder): con x264 a RF ≤ 20 un bitrate medio basso vuol dire solo
// che la scena si comprime bene (o che i fotogrammi sono duplicati da 30 a 60), non che manca qualità.
export function evaluate(info, analysis, encoder = null) {
  const shortSide = Math.round(Math.min(info.width, info.height));
  const fps = analysis?.medianFps || info.fps;
  const checks = [];
  const add = (id, state, label, value, detail) => checks.push({ id, state, label, value, detail });

  add("codec", H264.has(info.codec) ? "ok" : "bad", "Codec", H264.has(info.codec) ? "H.264" : info.codec.toUpperCase(),
    H264.has(info.codec) ? "Like every untouched post we found." : "The untouched posts we found were all H.264.");
  add("size", shortSide <= MAX_SHORT_SIDE ? "ok" : "bad", "Resolution", `${Math.round(info.width)}×${Math.round(info.height)}`,
    shortSide <= MAX_SHORT_SIDE ? "Short side within 1080 px." : `Short side ${shortSide} px: it needs to come down to 1080.`);
  add("fps", fps >= 50 ? "ok" : "bad", "Frame rate", `${round(fps)} FPS`,
    fps >= 50 ? "The untouched posts we found were all 60 FPS."
      : "The untouched posts we found were all 60 FPS: converting is the safe choice.");
  if (analysis) {
    add("cfr", analysis.constantFps ? "ok" : "warn", "Frame timing", analysis.constantFps ? "Constant" : "Variable",
      analysis.constantFps ? "Every frame lasts the same." : `${analysis.irregularFrames} frames off the beat: in HandBrake pick “Constant Framerate”.`);
    const avg = analysis.averageMbps;
    const crf = encoder?.encoder === "x264" && encoder.options?.rc === "crf" ? Number(encoder.options.crf) : NaN;
    const lowOk = avg < 6 && crf <= 20;
    add("average", lowOk ? "ok" : avg < 6 ? "warn" : avg > 25 ? "warn" : "ok", "Average bitrate", `${fixed(avg)} Mbps`,
      lowOk ? `Low because it compresses well: at RF ${fixed(crf, 0)} x264 sets the quality, not the Mbps.`
        : avg < 6 ? "Low: the quality of your file is what viewers will see."
          : avg > 25 ? "Heavy for viewers on mobile data; TikTok still accepted a post we checked at 66 Mbps."
            : "In the range of the posts we checked.");
    const peak = analysis.peakMbps;
    add("peak", peak <= PEAK_OK ? "ok" : "warn", "Peak over 1 second", `${fixed(peak)} Mbps`,
      peak <= PEAK_OK ? "Smooth even on average connections."
        : `${peak > PEAK_HIGH ? "Very high" : "High"} at ${fixed(analysis.peakAt, 1)} s: viewers with less than ${Math.ceil(peak)} Mbps may see a pause. It doesn't seem to trigger re-encoding (an untouched post we checked peaked at 42).`);
    const audio = analysis.audio;
    add("audio", !audio ? "info" : audio.codec === "aac" ? "ok" : "warn", "Audio",
      !audio ? "None" : `${audio.codec.toUpperCase()} · ${audio.channels === 1 ? "mono" : audio.channels === 2 ? "stereo" : `${audio.channels} channels`} · ${Math.round(audio.sampleRate / 1000)} kHz`,
      !audio ? "The video has no audio track." : audio.codec === "aac" ? "The standard format for MP4." : "AAC recommended: export the audio as AAC.");
    if (analysis.keyInterval) {
      add("keys", "info", "Keyframes", `every ${fixed(analysis.keyInterval)} s`, "For information: not linked to re-encoding.");
    }
  }
  const needs = {
    codec: !H264.has(info.codec),
    resize: shortSide > MAX_SHORT_SIDE,
    fps: fps < 50,
    cfr: analysis ? !analysis.constantFps : false,
  };
  const blocking = needs.codec || needs.resize || needs.fps;
  const warnings = checks.some((check) => check.state === "warn");
  return {
    checks,
    needs,
    verdict: blocking ? "fix" : warnings ? "warn" : "ready",
  };
}

// options: { force60, maxMbps, encode, audioCodec } — audioCodec "aac" viene copiato come fa HandBrake, il resto ricodificato.
// onProgress riceve { value, frame, speed, eta } durante la ricodifica.
export async function prepareOriginalVideo(file, info, options = {}, onProgress = () => {}) {
  if (info.alreadyPatched) throw new Error("Pick the original video, without the patch.");
  const plan = originalPlan(info, options);
  let buffer;
  if (plan.reencode) {
    const result = await encodeLikeHandBrake(file, {
      shortSide: Math.round(Math.min(plan.width, plan.height)), resize: plan.resize, fps: plan.rate, maxMbps: plan.maxMbps,
    }, { audioCodec: options.audioCodec, seconds: info.seconds }, onProgress);
    buffer = result.buffer;
    plan.threads = result.threads;
  } else {
    buffer = await file.arrayBuffer();
  }
  const patched = globalThis.HQPatcher.patch(buffer);
  const check = globalThis.HQPatcher.inspect(patched.output);
  if (check.patchKind !== "wtm206") throw new Error("The duration patch wasn't applied.");
  // Dopo la ricodifica si confrontano lato corto e lato lungo: ffmpeg applica la rotazione del telefono
  // e arrotonda il lato lungo al pari.
  const [w, h] = [Math.round(check.width), Math.round(check.height)];
  const [pw, ph] = [Math.round(plan.width), Math.round(plan.height)];
  const sizeOk = plan.reencode
    ? Math.min(w, h) === Math.min(pw, ph) && Math.abs(Math.max(w, h) - Math.max(pw, ph)) <= 4
    : w === pw && h === ph;
  if (!sizeOk) throw new Error(`The final resolution (${w}×${h}) doesn't match the expected one (${pw}×${ph}).`);
  if (plan.fps && Math.abs(check.fps - plan.fps) > 0.5) throw new Error(`The converted file is ${round(check.fps)} FPS instead of ${plan.fps}.`);
  return { output: patched.output, plan, check, transcoded: plan.reencode };
}

files.analysis.js:
// Analisi locale del file prima della patch: FPS reali e costanza, bitrate per
// secondo e picco su finestra mobile di 1 s, audio, keyframe. Legge solo i
// metadati dei campioni (dimensione e tempi), senza decodificare il video.
import { BlobSource, EncodedPacketSink, Input, MP4, QTFF } from "./vendor/mediabunny.min.mjs";

const nextPaint = () => new Promise((resolve) => setTimeout(resolve, 0));

export async function analyzeVideo(file, info, onProgress = () => {}) {
  const input = new Input({ source: new BlobSource(file), formats: [MP4, QTFF] });
  try {
    const tracks = (await input.getTracks()).filter((track) => track.type === "video" || track.type === "audio");
    const video = tracks.find((track) => track.type === "video");
    if (!video) throw new Error("The file has no video track.");
    const audio = tracks.find((track) => track.type === "audio") || null;
    const events = [];
    const frameTimes = [];
    let keyFrames = 0;
    for (let index = 0; index < tracks.length; index++) {
      const track = tracks[index];
      const isVideo = track === video;
      const sink = new EncodedPacketSink(track);
      for await (const packet of sink.packets(undefined, undefined, { metadataOnly: true })) {
        events.push({ time: Math.max(0, packet.timestamp), size: packet.byteLength });
        if (isVideo) {
          frameTimes.push(packet.timestamp);
          if (packet.type === "key") keyFrames++;
        }
        if (events.length % 4096 === 0) await nextPaint();
      }
      onProgress((index + 1) / tracks.length);
    }
    if (!frameTimes.length) throw new Error("The file has no video frames.");

    // Picco: byte audio+video nella finestra (t - 1 s, t], come compressor.js.
    events.sort((a, b) => a.time - b.time);
    let first = 0, windowBytes = 0, peakBytes = 0, peakAt = 0;
    for (let last = 0; last < events.length; last++) {
      windowBytes += events[last].size;
      while (events[first].time <= events[last].time - 1 + 1e-9) windowBytes -= events[first++].size;
      if (windowBytes > peakBytes) { peakBytes = windowBytes; peakAt = events[last].time; }
    }
    const seconds = info.seconds;
    const buckets = new Array(Math.max(1, Math.ceil(seconds))).fill(0);
    for (const event of events) buckets[Math.min(buckets.length - 1, Math.floor(event.time))] += event.size;
    const perSecond = buckets.map((bytes, i) => {
      const span = i === buckets.length - 1 ? Math.max(0.25, seconds - i) : 1;
      return bytes * 8 / span / 1e6;
    });
    // Minimo sui secondi interi: l'ultimo spezzone corto falserebbe il valore.
    const whole = Math.max(1, Math.floor(seconds));
    let minAt = 0;
    for (let i = 1; i < Math.min(whole, perSecond.length); i++) if (perSecond[i] < perSecond[minAt]) minAt = i;

    // Costanza degli FPS: intervalli tra fotogrammi in ordine di presentazione.
    frameTimes.sort((a, b) => a - b);
    const deltas = [];
    for (let i = 1; i < frameTimes.length; i++) deltas.push(frameTimes[i] - frameTimes[i - 1]);
    const sorted = [...deltas].sort((a, b) => a - b);
    const median = sorted.length ? sorted[Math.floor(sorted.length / 2)] : 0;
    const tolerance = Math.max(0.0015, median * 0.2);
    const irregular = deltas.filter((delta) => Math.abs(delta - median) > tolerance).length;
    const constantFps = deltas.length < 2 || irregular <= Math.max(1, deltas.length * 0.01);

    let audioInfo = null;
    if (audio) {
      audioInfo = {
        codec: await audio.getCodec(),
        channels: audio.numberOfChannels,
        sampleRate: audio.sampleRate,
      };
    }
    let codecString = null;
    try { codecString = await video.getCodecParameterString(); } catch {}
    return {
      averageMbps: file.size * 8 / seconds / 1e6,
      peakMbps: peakBytes * 8 / 1e6,
      peakAt,
      minMbps: perSecond[minAt],
      minAt,
      perSecond,
      fps: info.fps,
      medianFps: median > 0 ? 1 / median : info.fps,
      constantFps,
      irregularFrames: irregular,
      frames: frameTimes.length,
      keyFrames,
      keyInterval: keyFrames ? seconds / keyFrames : null,
      codecString,
      audio: audioInfo,
    };
  } finally {
    input.dispose();
  }
}

files.encoder.js:
// Riconosce programma ed encoder dalle stringhe che lasciano nel file (SEI di x264,
// tag ©too di HandBrake e FFmpeg, XMP di Adobe) e giudica la compressione rispetto
// al preset HQ Upload. Legge solo l'inizio e la fine del file, senza decodificare.
import { PEAK_OK } from "./original.js";

const HEAD = 8 * 1024 * 1024;
const TAIL = 2 * 1024 * 1024;
const PRESETS = { 0: "ultrafast", 1: "superfast", 2: "veryfast", 4: "faster", 6: "fast", 7: "medium", 8: "slow", 9: "slower", 10: "veryslow", 11: "placebo" };
const fixed = (value, digits = 1) => value.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });

export async function detectEncoder(file) {
  const parts = [file.slice(0, Math.min(file.size, HEAD))];
  if (file.size > HEAD) parts.push(file.slice(Math.max(HEAD, file.size - TAIL)));
  const decoder = new TextDecoder("latin1");
  const text = (await Promise.all(parts.map((part) => part.arrayBuffer()))).map((buffer) => decoder.decode(buffer)).join("\n");

  const handbrake = text.match(/HandBrake (\d+\.\d+(?:\.\d+)?)/);
  const adobe = text.match(/Adobe (After Effects|Media Encoder|Premiere Pro)(?: (\d{4}))?/);
  const lavf = /Lavf\d+/.test(text);
  const app = handbrake ? `HandBrake ${handbrake[1]}`
    : adobe ? `Adobe ${adobe[1]}${adobe[2] ? ` ${adobe[2]}` : ""}`
      : lavf ? "FFmpeg" : null;

  const sei = text.match(/x264 - core (\d+)[^\x00]{0,400}?options: ([^\x00]{1,4000})/);
  if (sei) {
    const options = Object.fromEntries(sei[2].trim().split(/\s+/).map((pair) => {
      const at = pair.indexOf("=");
      return at > 0 ? [pair.slice(0, at), pair.slice(at + 1)] : [pair, ""];
    }));
    const subme = Number(options.subme);
    return { app, encoder: "x264", core: Number(sei[1]), options, preset: PRESETS[subme] || null, subme };
  }
  if (/x265 \(build \d+\)/.test(text)) return { app, encoder: "x265", options: null };
  return { app, encoder: null, options: null };
}

// rows: { label, value, state } con state ok | warn | bad | info. tips: consigli concreti.
export function assessCompression(encoder, info, analysis) {
  const rows = [];
  const tips = [];
  const add = (label, value, state) => rows.push({ label, value, state });
  const peak = analysis?.peakMbps ?? null;
  let matchesPreset = false;
  let known = false;

  add("Software", encoder?.app || "Not stated in the file", "info");
  if (encoder?.encoder === "x264" && encoder.options) {
    known = true;
    const o = encoder.options;
    const subme = encoder.subme;
    const presetState = subme >= 8 ? "ok" : subme === 7 ? "info" : "warn";
    add("Encoder", `x264${encoder.preset ? ` · preset ${encoder.preset}` : ""}`, presetState);
    if (subme === 7) tips.push("Preset “medium”: with “slow” the file comes out sharper at the same size.");
    else if (subme < 7) tips.push(`Preset “${encoder.preset || "fast"}”: quick, but it wastes quality. In HandBrake pick “slow”.`);

    if (o.rc === "crf") {
      const crf = Number(o.crf);
      const level = crf <= 18 ? "high" : crf <= 20 ? "good" : crf <= 23 ? "medium" : "low";
      add("Quality", `RF ${fixed(crf, crf % 1 ? 1 : 0)} · ${level}`, crf <= 20 ? "ok" : "warn");
      if (crf > 20) tips.push(`RF ${fixed(crf, 0)}: lower it to 18. A lower number means more detail.`);
    } else if (Number(o.bitrate) > 0) {
      add("Quality", `Fixed bitrate ${fixed(Number(o.bitrate) / 1000)} Mbps`, "info");
      tips.push("Fixed bitrate: with constant quality (RF 18) the hard scenes stay sharp.");
    } else if (o.rc) {
      add("Quality", `Rate control ${o.rc}`, "info");
    }

    // Il limite dei picchi è una scelta, non un errore: senza limite la qualità resta piena,
    // e se i picchi sono alti lo dice la scheda "Picchi".
    const vbv = Number(o.vbv_maxrate) || 0;
    const buffer = Number(o.vbv_bufsize) || 0;
    // Limite scelto in HQ Upload: maxrate 80% e buffer 20% di (limite − 0,5), vedi x264.js.
    const hqCap = vbv && Math.abs(buffer * 4 - vbv) <= 4 ? Math.round((vbv + buffer) / 1000 + 0.5) : 0;
    if (hqCap) add("Peak cap", `${hqCap} Mbps per 1 s (chosen in HQ Upload)`, "ok");
    else if (vbv) add("Peak cap", `${fixed(vbv / 1000, 0)} Mbps (VBV)`, "ok");
    else add("Peak cap", "None · full quality", peak > PEAK_OK ? "info" : "ok");
    matchesPreset = o.rc === "crf" && Number(o.crf) === 18 && subme >= 8;
  } else if (encoder?.encoder === "x265") {
    known = true;
    add("Encoder", "x265 · HEVC", "bad");
    tips.push("HEVC: the untouched posts we found were all H.264. In HandBrake pick H.264 (x264).");
  } else {
    add("Encoder", "Not recognised", "info");
  }

  if (!known && analysis && info.width && info.height) {
    const fps = analysis.medianFps || info.fps || 30;
    const bpp = analysis.averageMbps * 1e6 / (info.width * info.height * fps);
    add("Density", `${fixed(bpp, 2)} bits per pixel`, bpp < 0.04 ? "warn" : "info");
    if (bpp < 0.04) tips.push("Little data per pixel: for a clean export use HandBrake with the HQ Upload preset.");
  }

  const state = rows.some((row) => row.state === "bad") ? "bad"
    : rows.some((row) => row.state === "warn") ? "warn" : known ? "ok" : "info";
  const title = state === "ok" ? (matchesPreset ? "HQ Upload preset recognised" : "Well compressed")
    : state === "warn" ? "Compression could be better"
      : state === "bad" ? "Change the encoder" : "Settings not readable";
  const summary = state === "ok" ? "High quality: that's what viewers will see."
    : state === "warn" ? "The file is fine for the patch, but with these changes it would be sharper."
      : state === "bad" ? "The untouched posts we found were H.264: re-export as H.264."
        : "This encoder doesn't store its settings in the file: judge by the bitrate above.";
  return { state, title, summary, rows, tips, matchesPreset };
}

