// Ricodifica con x264, lo stesso encoder di HandBrake. Le impostazioni si decidono qui (e si aggiornano
// con l'app); il motore ffmpeg.wasm multi-thread sta nel guscio, che esegue la riga di comando con i
// segnaposto {input}, {output} e {threads} e riprova con meno thread se il core si blocca.
// Impostazioni del preset "HQ Upload TikTok … 60": x264 preset slow, RF 18, High@4.2, keyframe come HandBrake
// (minimo 1 s, massimo 10 s), FPS costanti (da 30 a 60 duplicando i fotogrammi), ridimensionamento lanczos
// senza ritagli, audio AAC copiato oppure ricodificato in AAC 320 kbps stereo.
// Di base nessun limite ai picchi (qualità piena); il limite si applica solo se l'utente lo sceglie.
// Prova del 3/11/2026 su un export reale 1920×1440 a 30 FPS: stesso PSNR/SSIM e stesso peso di x264 nativo.

// Con 12 o più thread x264 il core (32 thread, 1 GB di memoria) si interrompe al primo fotogramma:
// si parte da 8 e, se fallisce, si riprova con meno.
const THREAD_STEPS = [8, 4, 2];
const NTSC = [[24000, 1001], [30000, 1001], [60000, 1001]];

// Il guscio dice all'avvio se la sua pagina ha l'isolamento cross-origin che serve al motore.
export function x264Ready() {
  return !!window.HQ_CONTEXT?.isolated;
}

// 59.94 → 60000/1001, così il ritmo resta esatto e non si aggiungono fotogrammi doppi.
function exactRate(fps) {
  const ntsc = NTSC.find(([num, den]) => Math.abs(fps - num / den) < 0.01);
  if (ntsc) return `${ntsc[0]}/${ntsc[1]}`;
  return String(Math.round(fps * 1000) / 1000);
}

// Limite scelto in Mbps → VBV. In 1 s il video può inviare fino a maxrate + bufsize: dopo una scena calma
// il buffer pieno si svuota in un colpo. Prova del 3/11/2026 (x264 slow RF 18, 60 FPS, picco audio+video
// su 1 s, dettaglio improvviso): 24,5/24,5 → 44,9 Mbps; 22/8 → 29 Mbps con 1-8 thread. Qui la somma resta
// 0,5 Mbps sotto il limite (spazio per l'audio): 23,8 su 25 e 28,7 su 30 nel caso peggiore, 18-20 e
// 22-24 con dettaglio costante. Le scene sotto il limite non cambiano: decide RF 18.
export function vbvFor(maxMbps) {
  const budget = (maxMbps - 0.5) * 1000;
  return { maxrate: Math.round(budget * 0.8), bufsize: Math.round(budget * 0.2) };
}

// shortSide: lato corto finale (pari). Il lato lungo segue le proporzioni del video già ruotato.
// maxMbps: limite dei picchi su 1 s scelto dall'utente, oppure null per la qualità piena.
export function x264Args({ shortSide, resize, fps, maxMbps, audioCopy }) {
  const rate = Math.round(fps);
  const vbv = maxMbps ? vbvFor(maxMbps) : null;
  const filters = [];
  if (resize) {
    filters.push(`scale='if(gte(iw,ih),-2,${shortSide})':'if(gte(iw,ih),${shortSide},-2)':flags=lanczos+accurate_rnd`);
  }
  filters.push(`fps=${exactRate(fps)}`, "format=yuv420p");
  return [
    "-filter_threads", "2",
    "-threads", "4", "-i", "{input}",
    "-map", "0:v:0", "-map", "0:a:0?",
    "-vf", filters.join(","),
    "-c:v", "libx264", "-preset", "slow", "-crf", "18", "-profile:v", "high", "-level:v", "4.2",
    "-x264-params", `${vbv ? `vbv-maxrate=${vbv.maxrate}:vbv-bufsize=${vbv.bufsize}:` : ""}keyint=${rate * 10}:min-keyint=${rate}`,
    "-threads", "{threads}",
    ...(audioCopy ? ["-c:a", "copy"] : ["-c:a", "aac", "-b:a", "320k", "-ac", "2"]),
    "-movflags", "+faststart",
    "{output}",
  ];
}

// plan: { shortSide, resize, fps, maxMbps } con fps finale (60, oppure quello del file se resta invariato).
// onProgress riceve { value, frame, speed, eta } con value tra 0 e 1 ed eta in secondi.
export async function encodeLikeHandBrake(file, plan, { audioCodec = null, seconds = 0 } = {}, onProgress = () => {}) {
  if (!x264Ready()) throw new Error("The x264 conversion needs an up-to-date Chrome or Edge (multi-threaded WebAssembly).");
  const totalFrames = Math.max(1, Math.round(seconds * plan.fps));
  const stop = hq.on("ffmpeg", ({ frame, speed, threads }) => {
    onProgress({
      value: frame ? Math.min(0.99, frame / totalFrames) : 0, frame, speed, threads,
      eta: speed > 0 ? Math.max(0, (totalFrames - frame) / speed) : null,
    });
  });
  try {
    const result = await hq.call("ffmpeg", [{ file, args: x264Args({ ...plan, audioCopy: audioCodec === "aac" }), threadSteps: THREAD_STEPS }]);
    onProgress({ value: 1, frame: totalFrames, speed: 0, eta: 0, threads: result.threads });
    return result;
  } finally {
    stop();
  }
}
